  | 'solid' | 'metallic' | 'gold' | 'chrome' | 'glass' | 'brushed' 
  | 'carbon' | 'wood' | 'neon' | 'marble' | 'royal' | 'ice' 
  | 'lava' | 'ceramic' | 'void' | 'copper' | 'pearl' | 'aurora' 
  | 'digital' | 'plastic' | 'dotted';

export interface WheelConfig {
  items: string[];
  colorScheme: ColorScheme;
  borderWidth: number;
  borderColor: string;
  borderStyle: BorderStyle;
  hubRadius: number;
  hubColor: string;
  fontSize: number;
