export const DEFAULT_CONFIG: WheelConfig = {
  items: ['心愿清单', '说走就走', '深度睡眠', '健身打卡', '技能升级', '读书万卷', '职场进阶', '自由职业'],
  colorScheme: COLOR_SCHEMES[0],
  borderWidth: 20,
