import React, { useEffect, useRef } from 'react';
import { WheelConfig } from '../types';

interface WheelCanvasProps {
  config: WheelConfig;
  exportScale?: number;
  onCanvasReady?: (canvas: HTMLCanvasElement) => void;
}

export const WheelCanvas: React.FC<WheelCanvasProps> = ({ config, exportScale = 2, onCanvasReady }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const drawWheel = (canvas: HTMLCanvasElement, scale: number) => {
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const size = canvas.width;
    const center = size / 2;
    const outerRadius = (size / 2) - (8 * scale); 
    const radius = outerRadius - (config.borderWidth * scale);

    const { items, colorScheme, borderWidth, borderColor, borderStyle, hubRadius, hubColor, fontSize, fontFamily, fontWeight, fontColor } = config;

    ctx.clearRect(0, 0, size, size);
    if (items.length === 0) return;

    const sliceAngle = (2 * Math.PI) / items.length;

    // 1. 绘制扇区
    items.forEach((item, i) => {
      const startAngle = i * sliceAngle + (config.rotation * Math.PI / 180);
      const endAngle = startAngle + sliceAngle;

      ctx.beginPath();
      ctx.moveTo(center, center);
      ctx.arc(center, center, radius, startAngle, endAngle);
      ctx.closePath();

      ctx.fillStyle = colorScheme.colors[i % colorScheme.colors.length];
      ctx.fill();

      ctx.lineWidth = 0.5 * scale;
      ctx.strokeStyle = 'rgba(255,255,255,0.2)';
      ctx.stroke();

      if (config.showText) {
        ctx.save();
        ctx.translate(center, center);
        ctx.rotate(startAngle + sliceAngle / 2);

        ctx.textAlign = 'right';
        ctx.textBaseline = 'middle';
        ctx.fillStyle = fontColor;
        ctx.font = `${fontWeight} ${fontSize * scale}px ${fontFamily}`;

        const textRadius = radius - (15 * scale);
        const maxWidth = radius * 0.75;
        ctx.fillText(item, textRadius, 0, maxWidth);

        ctx.restore();
      }
    });

    // 2. 物理感边框绘制
    if (borderWidth > 0) {
      ctx.save();
      ctx.beginPath();
      ctx.arc(center, center, radius + (borderWidth * scale / 2), 0, 2 * Math.PI);
      ctx.lineWidth = borderWidth * scale;

      const gradX = center - outerRadius;
      const gradY = center - outerRadius;
      const gradX2 = center + outerRadius;
      const gradY2 = center + outerRadius;

      // --- Physical Texture Logic ---
      switch (borderStyle) {
        case 'gold': {
          const grad = ctx.createLinearGradient(gradX, gradY, gradX2, gradY2);
          grad.addColorStop(0, '#BF953F');
          grad.addColorStop(0.2, '#FCF6BA');
          grad.addColorStop(0.4, '#B38728');
          grad.addColorStop(0.6, '#FBF5B7');
          grad.addColorStop(1, '#AA771C');
          ctx.strokeStyle = grad;
          break;
        }
        case 'chrome': {
          const grad = ctx.createLinearGradient(gradX, gradY, gradX2, gradY2);
          grad.addColorStop(0, '#6A82FB');
          grad.addColorStop(0.25, '#FC5C7D');
          grad.addColorStop(0.5, '#05FFD1');
          grad.addColorStop(0.75, '#FC5C7D');
          grad.addColorStop(1, '#6A82FB');
          ctx.strokeStyle = grad;
          break;
        }
        case 'metallic': {
          const grad = ctx.createLinearGradient(center, center - outerRadius, center, center + outerRadius);
          grad.addColorStop(0, '#777');
          grad.addColorStop(0.5, '#eee');
          grad.addColorStop(1, '#555');
          ctx.strokeStyle = grad;
          break;
        }
        case 'glass': {
          ctx.strokeStyle = 'rgba(255,255,255,0.25)';
          ctx.shadowBlur = 20 * scale;
          ctx.shadowColor = 'rgba(255,255,255,0.5)';
          break;
        }
        case 'brushed': {
          const grad = ctx.createRadialGradient(center, center, radius, center, center, outerRadius);
          grad.addColorStop(0, '#333');
          grad.addColorStop(0.4, '#ddd');
          grad.addColorStop(0.6, '#bbb');
          grad.addColorStop(1, '#222');
          ctx.strokeStyle = grad;
          break;
        }
        case 'carbon': {
          const grad = ctx.createLinearGradient(gradX, gradY, gradX2, gradY2);
          grad.addColorStop(0, '#111');
          grad.addColorStop(0.2, '#333');
          grad.addColorStop(0.4, '#111');
          grad.addColorStop(0.6, '#333');
          grad.addColorStop(0.8, '#111');
          grad.addColorStop(1, '#333');
          ctx.strokeStyle = grad;
          break;
        }
        case 'wood': {
          const grad = ctx.createLinearGradient(gradX, gradY, gradX2, gradY2);
          grad.addColorStop(0, '#4b2c20');
          grad.addColorStop(0.3, '#795548');
          grad.addColorStop(0.6, '#5d4037');
          grad.addColorStop(1, '#3e2723');
          ctx.strokeStyle = grad;
          break;
        }
        case 'neon': {
          ctx.strokeStyle = '#00f3ff';
          ctx.shadowBlur = 30 * scale;
          ctx.shadowColor = '#00f3ff';
          break;
        }
        case 'marble': {
          const grad = ctx.createLinearGradient(gradX, gradY, gradX2, gradY2);
          grad.addColorStop(0, '#f5f5f5');
          grad.addColorStop(0.45, '#e0e0e0');
          grad.addColorStop(0.5, '#9e9e9e');
          grad.addColorStop(0.55, '#e0e0e0');
          grad.addColorStop(1, '#f5f5f5');
          ctx.strokeStyle = grad;
          break;
        }
        case 'royal': {
          const grad = ctx.createLinearGradient(gradX, gradY, gradX2, gradY2);
          grad.addColorStop(0, '#4a148c');
          grad.addColorStop(0.5, '#ffd700');
          grad.addColorStop(1, '#4a148c');
          ctx.strokeStyle = grad;
          break;
        }
        case 'ice': {
          const grad = ctx.createLinearGradient(gradX, gradY, gradX2, gradY2);
          grad.addColorStop(0, '#e1f5fe');
          grad.addColorStop(0.5, '#ffffff');
          grad.addColorStop(1, '#81d4fa');
          ctx.strokeStyle = grad;
          ctx.globalAlpha = 0.8;
          break;
        }
        case 'lava': {
          const grad = ctx.createLinearGradient(gradX, gradY, gradX2, gradY2);
          grad.addColorStop(0, '#d50000');
          grad.addColorStop(0.5, '#ff6d00');
          grad.addColorStop(1, '#d50000');
          ctx.strokeStyle = grad;
          ctx.shadowBlur = 15 * scale;
          ctx.shadowColor = '#ff3d00';
          break;
        }
        case 'ceramic': {
          const grad = ctx.createRadialGradient(center, center, radius, center, center, outerRadius);
          grad.addColorStop(0, '#ffffff');
          grad.addColorStop(0.9, '#f0f0f0');
          grad.addColorStop(1, '#cccccc');
          ctx.strokeStyle = grad;
          break;
        }
        case 'void': {
          ctx.strokeStyle = '#000000';
          ctx.shadowBlur = 10 * scale;
          ctx.shadowColor = 'rgba(255,255,255,0.1)';
          break;
        }
        case 'copper': {
          const grad = ctx.createLinearGradient(gradX, gradY, gradX2, gradY2);
          grad.addColorStop(0, '#b87333');
          grad.addColorStop(0.5, '#dd9c6b');
          grad.addColorStop(1, '#b87333');
          ctx.strokeStyle = grad;
          break;
        }
        case 'pearl': {
          const grad = ctx.createLinearGradient(gradX, gradY, gradX2, gradY2);
          grad.addColorStop(0, '#fff5f8');
          grad.addColorStop(0.3, '#e0f7fa');
          grad.addColorStop(0.7, '#f3e5f5');
          grad.addColorStop(1, '#fff5f8');
          ctx.strokeStyle = grad;
          break;
        }
        case 'aurora': {
          const grad = ctx.createLinearGradient(gradX, gradY, gradX2, gradY2);
          grad.addColorStop(0, '#00e676');
          grad.addColorStop(0.5, '#6200ea');
          grad.addColorStop(1, '#00e676');
          ctx.strokeStyle = grad;
          break;
        }
        case 'digital': {
          ctx.strokeStyle = '#0f0';
          ctx.shadowBlur = 5 * scale;
          ctx.shadowColor = '#0f0';
          ctx.setLineDash([2 * scale, 4 * scale]);
          break;
        }
        case 'plastic': {
          ctx.strokeStyle = '#37474f';
          break;
        }
        default:
          ctx.strokeStyle = borderColor;
          if (borderStyle === 'dotted') ctx.setLineDash([4 * scale, 8 * scale]);
          break;
      }

      ctx.stroke();
      ctx.restore();
    }

    // 3. 中心轴承
    if (hubRadius > 0) {
      ctx.beginPath();
      ctx.arc(center, center, hubRadius * scale, 0, 2 * Math.PI);

      const hubGrad = ctx.createRadialGradient(center - hubRadius/3, center - hubRadius/3, 0, center, center, hubRadius * scale);
      hubGrad.addColorStop(0, '#fff');
      hubGrad.addColorStop(1, hubColor);
      ctx.fillStyle = hubGrad;

      ctx.fill();
      ctx.lineWidth = 1 * scale;
      ctx.strokeStyle = 'rgba(0,0,0,0.1)';
      ctx.stroke();
    }
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const scale = exportScale;
    const displaySize = 1000; 
    canvas.width = displaySize * scale;
    canvas.height = displaySize * scale;
    canvas.style.width = `100%`;
    canvas.style.height = `100%`;

    drawWheel(canvas, scale);
    if (onCanvasReady) onCanvasReady(canvas);
  }, [config, exportScale]);

  return (
    <div className="w-full h-full flex justify-center items-center bg-transparent p-0 overflow-hidden">
      <canvas 
        ref={canvasRef} 
        className="max-w-full max-h-full object-contain drop-shadow-[0_40px_100px_rgba(0,0,0,0.6)]"
      />
    </div>
  );
};

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { WheelCanvas } from './components/WheelCanvas';
import { COLOR_SCHEMES, DEFAULT_CONFIG, CHINESE_FONTS, APP_VERSION, BORDER_STYLES } from './constants';
import { WheelConfig, ColorScheme, BorderStyle } from './types';
import { GoogleGenAI } from "@google/genai";

const App: React.FC = () => {
  const [config, setConfig] = useState<WheelConfig>(DEFAULT_CONFIG);
  const [textInput, setTextInput] = useState(DEFAULT_CONFIG.items.join('\n'));
  const canvasRef = useRef<HTMLCanvasElement | null>(null);

  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<{ role: 'user' | 'ai', content: string, items?: string[] }[]>([
    { role: 'ai', content: `嗨！我是你的灵感助手。请输入你想要的主题和具体的格子数量（例如：50个2026年必做清单），我会严格为你生成！` }
  ]);
  const [isAiLoading, setIsAiLoading] = useState(false);

  const handleTextChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const value = e.target.value;
    setTextInput(value);
    const items = value.split('\n').filter(line => line.trim() !== '');
    setConfig(prev => ({ ...prev, items }));
  };

  const updateConfig = (updates: Partial<WheelConfig>) => {
    setConfig(prev => ({ ...prev, ...updates }));
  };

  const downloadImage = () => {
    if (!canvasRef.current) return;
    const link = document.createElement('a');
    link.download = `wheel-ultra-hd-${APP_VERSION}-${Date.now()}.png`;
    link.href = canvasRef.current.toDataURL('image/png', 1.0);
    link.click();
  };

  const callAi = async () => {
    if (!chatInput.trim() || isAiLoading) return;
    const userMsg = chatInput;
    setChatInput('');
    setChatHistory(prev => [...prev, { role: 'user', content: userMsg }]);
    setIsAiLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `用户需求: ${userMsg}. 
        任务：严格执行生成任务。
        规则：
        1. 必须精准识别用户提到的【数量】。如果提到50个，你就必须输出50行。绝对不能偷懒、合并或省略。
        2. 返回格式：一段简短友好的回复，后面跟着每行一个选项的列表。
        3. 列表内容不要序号、不要前缀符号，直接输出文案。
        4. 风格：年轻、潮流、现代。`,
        config: {
          systemInstruction: "你是一个极其严谨且富有创意的转盘策划。你的信条是：用户要多少，我就给多少。绝对不打折扣，不缩减内容。"
        }
      });

      const aiText = response.text || '';
      const lines = aiText.split('\n');
      const detectedItems = lines
        .map(l => l.replace(/^[-*•\d.]+\s*/, '').trim())
        .filter(l => l.length > 0 && l.length < 40 && !l.includes('```') && !l.includes(':') && !l.includes('：'));

      setChatHistory(prev => [...prev, { 
        role: 'ai', 
        content: aiText,
        items: detectedItems.length > 0 ? detectedItems : undefined 
      }]);
    } catch (error) {
      setChatHistory(prev => [...prev, { role: 'ai', content: '抱歉，大脑宕机了，请重新尝试。' }]);
    } finally {
      setIsAiLoading(false);
    }
  };

  const applyAiItems = (items: string[]) => {
    const text = items.join('\n');
    setTextInput(text);
    setConfig(prev => ({ ...prev, items }));
  };

  const inputBaseClass = "w-full bg-slate-800 text-white border border-slate-700 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm transition-all placeholder-slate-500";

  return (
    <div className="flex flex-col md:flex-row h-screen overflow-hidden bg-slate-900 text-slate-100 font-sans">

      {/* 第一列：参数配置 */}
      <div className="w-full md:w-80 bg-slate-950 border-r border-white/5 overflow-y-auto p-5 flex flex-col gap-6 shadow-2xl z-20">
        <header className="flex items-center justify-between">
          <div>
            <h1 className="text-xl font-black text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-emerald-400">转盘工厂</h1>
            <p className="text-[10px] text-slate-500 uppercase font-bold tracking-widest">Version {APP_VERSION}</p>
          </div>
        </header>

        <section className="space-y-4">
          <div className="flex items-center justify-between border-b border-white/5 pb-2">
             <h2 className="text-xs font-bold text-slate-500 uppercase tracking-widest">内容格子</h2>
             <span className="text-[10px] bg-slate-800 text-slate-400 px-2 py-0.5 rounded-full">{config.items.length}</span>
          </div>
          <textarea
            className={`${inputBaseClass} h-32 p-3 resize-none border-white/10`}
            value={textInput}
            onChange={handleTextChange}
            placeholder="每行一个内容..."
          />
        </section>

        <section className="space-y-4">
          <h2 className="text-xs font-bold text-slate-500 uppercase tracking-widest border-b border-white/5 pb-2">外观与质感</h2>

          <div>
            <label className="block text-xs font-semibold text-slate-500 mb-1.5">色彩主题</label>
            <select
              value={config.colorScheme.name}
              onChange={(e) => {
                const scheme = COLOR_SCHEMES.find(s => s.name === e.target.value);
                if (scheme) updateConfig({ colorScheme: scheme });
              }}
              className={`${inputBaseClass} p-2.5 bg-slate-900`}
            >
              {COLOR_SCHEMES.map(s => <option key={s.name} value={s.name}>{s.name}</option>)}
            </select>
          </div>

          <div>
            <label className="block text-xs font-semibold text-slate-500 mb-1.5">物理质感 (20种)</label>
            <select
              value={config.borderStyle}
              onChange={(e) => updateConfig({ borderStyle: e.target.value as BorderStyle })}
              className={`${inputBaseClass} p-2.5 bg-slate-900 border-blue-500/30 font-semibold`}
            >
              {BORDER_STYLES.map(style => (
                <option key={style.id} value={style.id}>{style.name}</option>
              ))}
            </select>
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-[10px] text-slate-500 mb-1">边框宽度</label>
              <input type="number" min="0" max="80" value={config.borderWidth} onChange={(e) => updateConfig({ borderWidth: Number(e.target.value) })} className={`${inputBaseClass} p-2`} />
            </div>
            <div>
              <label className="block text-[10px] text-slate-500 mb-1">轴心半径</label>
              <input type="number" min="0" max="150" value={config.hubRadius} onChange={(e) => updateConfig({ hubRadius: Number(e.target.value) })} className={`${inputBaseClass} p-2`} />
            </div>
          </div>
        </section>

        <section className="space-y-4">
          <h2 className="text-xs font-bold text-slate-500 uppercase tracking-widest border-b border-white/5 pb-2">排版</h2>
          <div>
            <label className="block text-xs font-semibold text-slate-500 mb-1.5">潮流字体</label>
            <select
              value={config.fontFamily}
              onChange={(e) => updateConfig({ fontFamily: e.target.value })}
              className={`${inputBaseClass} p-2.5 bg-slate-900`}
            >
              {CHINESE_FONTS.map(f => <option key={f.value} value={f.value}>{f.name}</option>)}
            </select>
          </div>
          <div className="grid grid-cols-2 gap-3 pb-6">
            <div>
              <label className="block text-[10px] text-slate-500 mb-1">字号</label>
              <input type="number" min="8" max="80" value={config.fontSize} onChange={(e) => updateConfig({ fontSize: Number(e.target.value) })} className={`${inputBaseClass} p-2`} />
            </div>
            <div>
              <label className="block text-[10px] text-slate-500 mb-1">颜色</label>
              <input type="color" value={config.fontColor} onChange={(e) => updateConfig({ fontColor: e.target.value })} className="w-full h-8 cursor-pointer rounded-lg border border-white/10 bg-slate-900 p-0" />
            </div>
          </div>
        </section>
      </div>

      {/* 第二列：AI 对话 */}
      <div className="w-full md:w-96 bg-slate-900 border-r border-white/5 flex flex-col h-full z-10">
        <div className="p-4 border-b border-white/5 bg-slate-900/80 backdrop-blur-lg flex items-center justify-between">
          <h2 className="text-sm font-bold flex items-center gap-2 text-blue-400">
            <span className="w-2 h-2 bg-emerald-400 rounded-full animate-ping"></span>
            灵感实验室
          </h2>
          <span className="text-[9px] bg-blue-500/20 text-blue-400 px-2 py-0.5 rounded-full font-bold">SMART GENERATE</span>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-4 scroll-smooth scrollbar-hide">
          {chatHistory.map((msg, idx) => (
