import React, { useEffect, useRef } from 'react';
import { WheelConfig } from '../types';

interface WheelCanvasProps {
  config: WheelConfig;
  exportScale?: number;
  onCanvasReady?: (canvas: HTMLCanvasElement) => void;
}

export const WheelCanvas: React.FC<WheelCanvasProps> = ({ config, exportScale = 2, onCanvasReady }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const drawWheel = (canvas: HTMLCanvasElement, scale: number) => {
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const size = canvas.width;
    const center = size / 2;
    const outerRadius = (size / 2) - (10 * scale); 
    const radius = outerRadius - (config.borderWidth * scale);

    const { items, colorScheme, borderWidth, borderStyle, hubRadius, hubColor, fontSize, fontFamily, fontWeight, fontColor, rotation } = config;

    ctx.clearRect(0, 0, size, size);
    if (items.length === 0) return;

    const sliceAngle = (2 * Math.PI) / items.length;

    // --- Helper: Create Texture Patterns ---
    const createNoisePattern = (color1: string, color2: string, size: number) => {
      const pCanvas = document.createElement('canvas');
      pCanvas.width = size;
      pCanvas.height = size;
      const pCtx = pCanvas.getContext('2d')!;
      pCtx.fillStyle = color1;
      pCtx.fillRect(0, 0, size, size);
      for (let i = 0; i < size * size * 0.1; i++) {
        pCtx.fillStyle = color2;
        pCtx.fillRect(Math.random() * size, Math.random() * size, 1, 1);
      }
      return ctx.createPattern(pCanvas, 'repeat')!;
    };

    // 1. Draw Slices
    items.forEach((item, i) => {
      const startAngle = i * sliceAngle + (rotation * Math.PI / 180);
      const endAngle = startAngle + sliceAngle;

      ctx.beginPath();
      ctx.moveTo(center, center);
      ctx.arc(center, center, radius, startAngle, endAngle);
      ctx.closePath();

      ctx.fillStyle = colorScheme.colors[i % colorScheme.colors.length];
      ctx.fill();

      // Delicate sector border
      ctx.lineWidth = 0.5 * scale;
      ctx.strokeStyle = 'rgba(255,255,255,0.15)';
      ctx.stroke();

      if (config.showText) {
        ctx.save();
        ctx.translate(center, center);
        ctx.rotate(startAngle + sliceAngle / 2);
        ctx.textAlign = 'right';
        ctx.textBaseline = 'middle';
        ctx.fillStyle = fontColor;
        ctx.font = `${fontWeight} ${fontSize * scale}px ${fontFamily}`;
        const textRadius = radius - (20 * scale);
        ctx.fillText(item, textRadius, 0, radius * 0.7);
        ctx.restore();
      }
    });

    // 2. High-Fidelity Physical Border Rendering
    if (borderWidth > 0) {
      ctx.save();
      const bRadius = radius + (borderWidth * scale / 2);
      ctx.beginPath();
      ctx.arc(center, center, bRadius, 0, 2 * Math.PI);
      ctx.lineWidth = borderWidth * scale;

      const gradX1 = center - outerRadius, gradY1 = center - outerRadius;
      const gradX2 = center + outerRadius, gradY2 = center + outerRadius;

      switch (borderStyle) {
        case 'titanium': {
          const g = ctx.createLinearGradient(gradX1, gradY1, gradX2, gradY2);
          g.addColorStop(0, '#2c3e50');
          g.addColorStop(0.3, '#7f8c8d');
          g.addColorStop(0.5, '#bdc3c7');
          g.addColorStop(0.7, '#7f8c8d');
          g.addColorStop(1, '#2c3e50');
          ctx.strokeStyle = g;
          // Add brush lines
          ctx.stroke();
          ctx.lineWidth = 1 * scale;
          ctx.strokeStyle = 'rgba(255,255,255,0.05)';
          for (let r = radius; r < outerRadius; r += 2 * scale) {
            ctx.beginPath();
            ctx.arc(center, center, r, 0, Math.PI * 2);
            ctx.stroke();
          }
          break;
        }
        case 'polished_gold': {
          const g = ctx.createLinearGradient(gradX1, gradY1, gradX2, gradY2);
          g.addColorStop(0, '#8e5d0d');
          g.addColorStop(0.2, '#fcf6ba');
          g.addColorStop(0.4, '#b38728');
          g.addColorStop(0.5, '#fbf5b7');
          g.addColorStop(0.8, '#b38728');
          g.addColorStop(1, '#8e5d0d');
          ctx.strokeStyle = g;
          ctx.stroke();
          break;
        }
        case 'carbon_fiber': {
          ctx.strokeStyle = '#111';
          ctx.stroke();
          // Diagonal Pattern
          ctx.save();
          ctx.clip();
          ctx.lineWidth = 1 * scale;
          ctx.strokeStyle = '#222';
          for(let k = -size; k < size*2; k += 4 * scale) {
            ctx.beginPath();
            ctx.moveTo(k, 0); ctx.lineTo(k + size, size);
            ctx.stroke();
          }
          ctx.strokeStyle = '#0a0a0a';
          for(let k = -size; k < size*2; k += 4 * scale) {
            ctx.beginPath();
            ctx.moveTo(k + 2*scale, 0); ctx.lineTo(k + size + 2*scale, size);
            ctx.stroke();
          }
          ctx.restore();
          break;
        }
        case 'italian_leather': {
          ctx.strokeStyle = '#4a2c20';
          ctx.stroke();
          ctx.strokeStyle = createNoisePattern('rgba(0,0,0,0)', 'rgba(255,255,255,0.05)', 4 * scale);
          ctx.stroke();
          // Stitching
          ctx.beginPath();
          ctx.arc(center, center, radius + 4*scale, 0, Math.PI*2);
          ctx.setLineDash([4*scale, 4*scale]);
          ctx.lineWidth = 1 * scale;
          ctx.strokeStyle = 'rgba(255,255,255,0.2)';
          ctx.stroke();
          break;
        }
        case 'frosted_glass': {
          const g = ctx.createRadialGradient(center, center, radius, center, center, outerRadius);
          g.addColorStop(0, 'rgba(255,255,255,0.4)');
          g.addColorStop(0.5, 'rgba(255,255,255,0.1)');
          g.addColorStop(1, 'rgba(255,255,255,0.4)');
          ctx.strokeStyle = g;
          ctx.shadowBlur = 15 * scale;
          ctx.shadowColor = 'rgba(255,255,255,0.3)';
          ctx.stroke();
          break;
        }
        case 'cyber_neon': {
          ctx.strokeStyle = '#00f3ff';
          ctx.shadowBlur = 20 * scale;
          ctx.shadowColor = '#00f3ff';
          ctx.stroke();
          // Moving light dots simulation based on rotation
          const dots = 12;
          for(let i=0; i<dots; i++){
            const angle = (i * (360/dots) + rotation*2) * Math.PI/180;
            ctx.beginPath();
            ctx.arc(center + Math.cos(angle)*bRadius, center + Math.sin(angle)*bRadius, 3*scale, 0, Math.PI*2);
            ctx.fillStyle = '#fff';
            ctx.fill();
          }
          break;
        }
        case 'luxury_silk': {
          const g = ctx.createConicGradient(rotation * Math.PI/180, center, center);
          g.addColorStop(0, '#c0392b');
          g.addColorStop(0.25, '#e74c3c');
          g.addColorStop(0.5, '#c0392b');
          g.addColorStop(0.75, '#e74c3c');
          g.addColorStop(1, '#c0392b');
          ctx.strokeStyle = g;
          ctx.stroke();
          break;
        }
        case 'obsidian_mirror': {
          ctx.strokeStyle = '#050505';
          ctx.stroke();
          // Sharp specular highlight
          const sg = ctx.createLinearGradient(gradX1, gradY1, center, center);
          sg.addColorStop(0, 'rgba(255,255,255,0.4)');
          sg.addColorStop(0.2, 'rgba(255,255,255,0)');
          ctx.strokeStyle = sg;
          ctx.stroke();
          break;
        }
        case 'diamond_cut': {
          ctx.strokeStyle = '#fff';
          ctx.stroke();
          ctx.save();
          ctx.clip();
          for(let i=0; i<36; i++) {
            const a = i * 10 * Math.PI/180;
            const g = ctx.createLinearGradient(center, center, center + Math.cos(a)*outerRadius, center + Math.sin(a)*outerRadius);
            g.addColorStop(0, 'rgba(255,255,255,0)');
            g.addColorStop(1, `hsla(${(i*20 + rotation)%360}, 70%, 70%, 0.4)`);
            ctx.fillStyle = g;
            ctx.beginPath();
            ctx.moveTo(center, center);
            ctx.arc(center, center, outerRadius, a, a + 10*Math.PI/180);
            ctx.fill();
          }
          ctx.restore();
          break;
        }
        case 'natural_wood': {
          ctx.strokeStyle = '#3d2b1f';
          ctx.stroke();
          ctx.lineWidth = 1 * scale;
          ctx.strokeStyle = 'rgba(0,0,0,0.2)';
          for (let r = radius; r < outerRadius; r += 3 * scale) {
            const rx = (Math.random()-0.5)*scale;
            ctx.beginPath();
            ctx.arc(center + rx, center + rx, r, 0, Math.PI * 2);
            ctx.stroke();
          }
          break;
        }
        case 'digital_grid': {
          ctx.strokeStyle = '#001a1a';
          ctx.stroke();
          ctx.save(); ctx.clip();
          ctx.lineWidth = 0.5 * scale;
          ctx.strokeStyle = 'rgba(0, 255, 255, 0.2)';
          for(let i=0; i<size; i += 8*scale) {
             ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i, size); ctx.stroke();
             ctx.beginPath(); ctx.moveTo(0, i); ctx.lineTo(size, i); ctx.stroke();
          }
          ctx.restore();
          break;
        }
        case 'lava_flow': {
          const g = ctx.createRadialGradient(center, center, radius, center, center, outerRadius);
          g.addColorStop(0, '#330000');
          g.addColorStop(0.6, '#ff4500');
          g.addColorStop(1, '#330000');
          ctx.strokeStyle = g;
          ctx.shadowBlur = 20 * scale;
          ctx.shadowColor = '#ff4500';
          ctx.stroke();
          break;
        }
        case 'pearl_essence': {
          const g = ctx.createConicGradient(rotation * Math.PI/90, center, center);
          g.addColorStop(0, '#efd5ff');
          g.addColorStop(0.3, '#d5f3ff');
          g.addColorStop(0.6, '#ffd5d5');
          g.addColorStop(1, '#efd5ff');
          ctx.strokeStyle = g;
          ctx.stroke();
          break;
        }
        case 'industrial_steel': {
          const g = ctx.createLinearGradient(center - outerRadius, center, center + outerRadius, center);
          g.addColorStop(0, '#444');
          g.addColorStop(0.5, '#aaa');
          g.addColorStop(1, '#444');
          ctx.strokeStyle = g;
          ctx.stroke();
          // Vertical Scratches
          ctx.save(); ctx.clip();
          ctx.lineWidth = 0.5 * scale;
          ctx.strokeStyle = 'rgba(255,255,255,0.1)';
          for(let i=0; i<size; i+=2*scale){
            ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i, size); ctx.stroke();
          }
          ctx.restore();
          break;
        }
        default: {
          ctx.strokeStyle = '#333';
          ctx.stroke();
          break;
        }
      }

      // Top Reflection / Lighting (Global)
      const lightGrad = ctx.createLinearGradient(gradX1, gradY1, center, center);
      lightGrad.addColorStop(0, 'rgba(255,255,255,0.2)');
      lightGrad.addColorStop(1, 'rgba(255,255,255,0)');
      ctx.strokeStyle = lightGrad;
      ctx.stroke();

      ctx.restore();
    }

    // 3. Central Hub with Depth
    if (hubRadius > 0) {
      ctx.save();
      ctx.beginPath();
      ctx.arc(center, center, hubRadius * scale, 0, 2 * Math.PI);

      const hubGrad = ctx.createRadialGradient(center - hubRadius/2, center - hubRadius/2, 0, center, center, hubRadius * scale);
      hubGrad.addColorStop(0, '#ffffff');
      hubGrad.addColorStop(0.8, hubColor);
      hubGrad.addColorStop(1, '#999');
      ctx.fillStyle = hubGrad;
      ctx.shadowBlur = 10 * scale;
      ctx.shadowColor = 'rgba(0,0,0,0.3)';
      ctx.fill();

      ctx.lineWidth = 2 * scale;
      ctx.strokeStyle = 'rgba(0,0,0,0.1)';
      ctx.stroke();
      ctx.restore();
    }
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const scale = exportScale;
    const displaySize = 1000; 
    canvas.width = displaySize * scale;
    canvas.height = displaySize * scale;
    drawWheel(canvas, scale);
    if (onCanvasReady) onCanvasReady(canvas);
  }, [config, exportScale]);

  return (
    <div className="w-full h-full flex justify-center items-center bg-transparent p-0 overflow-hidden">
      <canvas 
        ref={canvasRef} 
        className="max-w-full max-h-full object-contain drop-shadow-[0_60px_120px_rgba(0,0,0,0.7)]"
      />
    </div>
  );
};

