    const animate = () => {
      if (isRotating) {
        setConfig(prev => ({ ...prev, rotation: (prev.rotation + 0.5) % 360 }));
      }
      animationId = requestAnimationFrame(animate);
    };
    animationId = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(animationId);
  }, [isRotating]);

  const handleTextChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const value = e.target.value;
    setTextInput(value);
    const items = value.split('\n').filter(line => line.trim() !== '');
    setConfig(prev => ({ ...prev, items }));
  };

  const updateConfig = (updates: Partial<WheelConfig>) => {
    setConfig(prev => ({ ...prev, ...updates }));
  };

  const downloadImage = () => {
    if (!canvasRef.current) return;
    const link = document.createElement('a');
    link.download = `wheel-pro-${config.borderStyle}-${Date.now()}.png`;
    link.href = canvasRef.current.toDataURL('image/png', 1.0);
    link.click();
  };

  const callAi = async () => {
    if (!chatInput.trim() || isAiLoading) return;
    const userMsg = chatInput;
    setChatInput('');
    setChatHistory(prev => [...prev, { role: 'user', content: userMsg }]);
    setIsAiLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `用户需求: ${userMsg}. 
        请帮用户生成转盘内容列表。
        要求：
        1. 严格按照用户要求的数量生成，每行一个。
        2. 为该主题建议一个最匹配的【物理质感】(选项包括: titanium, polished_gold, carbon_fiber, italian_leather, frosted_glass, cyber_neon, luxury_silk, industrial_steel, royal_velvet, obsidian_mirror, white_marble, natural_wood, diamond_cut, forged_carbon, aero_ceramic, vintage_copper, lava_flow, pearl_essence, canvas_fabric, digital_grid)。
        3. 建议一种色彩方案（给出主题名即可，如：活力彩虹, 极光霓虹, 莫兰迪等）。`,
        config: {
          systemInstruction: "你是一个专业的视觉设计师和文案专家。返回格式应包含：一段简短回复 + 列表清单 + 底部一行[STYLE:质感ID, COLOR:方案名]"
        }
      });

      const aiText = response.text || '';
      const lines = aiText.split('\n');
      const detectedItems = lines
        .filter(l => l.trim().length > 0 && !l.startsWith('[') && !l.includes(':'))
        .map(l => l.replace(/^[-*•\d.]+\s*/, '').trim());

      setChatHistory(prev => [...prev, { 
        role: 'ai', 
        content: aiText,
        items: detectedItems.length > 0 ? detectedItems : undefined 
      }]);
    } catch (error) {
      setChatHistory(prev => [...prev, { role: 'ai', content: '连接失败，请重试。' }]);
    } finally {
      setIsAiLoading(false);
    }
  };

  const applyAiItems = (items: string[]) => {
    const text = items.join('\n');
    setTextInput(text);
    setConfig(prev => ({ ...prev, items }));
  };

  const inputBaseClass = "w-full bg-slate-800 text-white border border-slate-700 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm transition-all";

  return (
    <div className="flex flex-col md:flex-row h-screen overflow-hidden bg-[#0a0a0c] text-slate-100 font-sans">

      {/* Sidebar: Config */}
      <div className="w-full md:w-80 bg-slate-950 border-r border-white/10 overflow-y-auto p-6 flex flex-col gap-8 shadow-2xl z-20">
        <header>
          <h1 className="text-2xl font-black italic tracking-tighter text-transparent bg-clip-text bg-gradient-to-br from-white to-slate-500">WHEEL GEN PRO</h1>
          <p className="text-[10px] text-blue-500 font-bold tracking-[0.3em] mt-1">INDUSTRIAL DESIGN ENGINE</p>
        </header>

        <section className="space-y-4">
          <div className="flex items-center justify-between border-b border-white/10 pb-2">
             <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Content Editor</h2>
             <span className="text-[10px] text-blue-400 font-mono">{config.items.length} SLOTS</span>
          </div>
          <textarea
            className={`${inputBaseClass} h-40 p-4 font-mono leading-relaxed bg-black/50 border-white/5`}
            value={textInput}
            onChange={handleTextChange}
            placeholder="Enter lines..."
          />
        </section>

        <section className="space-y-5">
          <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest border-b border-white/10 pb-2">Material & Texture</h2>

          <div className="space-y-3">
            <div>
              <label className="block text-[10px] text-slate-500 mb-1.5 uppercase font-bold">Physical Finish</label>
              <select
                value={config.borderStyle}
                onChange={(e) => updateConfig({ borderStyle: e.target.value as BorderStyle })}
                className={`${inputBaseClass} p-3 bg-slate-900 border-white/10 font-bold text-blue-400`}
              >
                {BORDER_STYLES.map(style => <option key={style.id} value={style.id}>{style.name}</option>)}
              </select>
            </div>

            <div>
              <label className="block text-[10px] text-slate-500 mb-1.5 uppercase font-bold">Color Palette</label>
              <select
                value={config.colorScheme.name}
                onChange={(e) => {
                  const scheme = COLOR_SCHEMES.find(s => s.name === e.target.value);
                  if (scheme) updateConfig({ colorScheme: scheme });
                }}
                className={`${inputBaseClass} p-3 bg-slate-900`}
              >
                {COLOR_SCHEMES.map(s => <option key={s.name} value={s.name}>{s.name}</option>)}
              </select>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <button 
              onClick={() => setIsRotating(!isRotating)}
              className={`py-3 rounded-xl text-[10px] font-black uppercase transition-all ${isRotating ? 'bg-emerald-500 text-black shadow-lg shadow-emerald-500/20' : 'bg-slate-800 text-slate-400'}`}
            >
              {isRotating ? 'Stop Rotation' : 'Simulate Spin'}
            </button>
            <div className="flex items-center justify-center gap-2 bg-slate-900 rounded-xl px-2">
              <span className="text-[10px] text-slate-500 font-bold">SPD</span>
              <input 
                type="range" min="0" max="360" value={config.rotation} 
                onChange={(e) => updateConfig({ rotation: Number(e.target.value) })}
                className="flex-1 accent-blue-500"
              />
            </div>
          </div>
        </section>

        <section className="space-y-4">
          <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest border-b border-white/10 pb-2">Typography</h2>
          <select
            value={config.fontFamily}
            onChange={(e) => updateConfig({ fontFamily: e.target.value })}
            className={`${inputBaseClass} p-3 bg-slate-900`}
          >
            {CHINESE_FONTS.map(f => <option key={f.value} value={f.value}>{f.name}</option>)}
          </select>
          <div className="grid grid-cols-2 gap-4">
            <div className="bg-slate-900 p-3 rounded-xl border border-white/5">
              <label className="block text-[9px] text-slate-500 mb-1 uppercase font-bold">Size</label>
              <input type="number" min="8" max="80" value={config.fontSize} onChange={(e) => updateConfig({ fontSize: Number(e.target.value) })} className="w-full bg-transparent text-white font-mono outline-none" />
            </div>
            <div className="bg-slate-900 p-3 rounded-xl border border-white/5 flex flex-col">
              <label className="block text-[9px] text-slate-500 mb-1 uppercase font-bold">Color</label>
              <input type="color" value={config.fontColor} onChange={(e) => updateConfig({ fontColor: e.target.value })} className="w-full h-6 cursor-pointer bg-transparent border-none p-0" />
            </div>
          </div>
        </section>
      </div>

      {/* Main Viewport */}
      <main className="flex-1 flex flex-col relative bg-[#010101]">
        {/* Abstract Background Elements */}
        <div className="absolute inset-0 overflow-hidden pointer-events-none opacity-20">
          <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-blue-500/20 blur-[150px] rounded-full"></div>
          <div className="absolute bottom-[-10%] right-[-10%] w-[50%] h-[50%] bg-purple-500/10 blur-[200px] rounded-full"></div>
          <div className="w-full h-full" style={{ backgroundImage: 'linear-gradient(#ffffff03 1px, transparent 1px), linear-gradient(90deg, #ffffff03 1px, transparent 1px)', backgroundSize: '40px 40px' }} />
        </div>

        <div className="p-6 flex items-center justify-between z-30 bg-black/40 backdrop-blur-xl border-b border-white/5">
          <div className="flex items-center gap-4">
            <div className="px-3 py-1 bg-white/10 border border-white/10 rounded-full text-[10px] font-black text-white">4K RENDER READY</div>
            <div className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">{config.borderStyle} Texture Active</div>
          </div>

          <button
            onClick={downloadImage}
            className="group px-8 py-3.5 bg-white text-black font-black rounded-full shadow-[0_20px_40px_rgba(255,255,255,0.15)] hover:scale-105 active:scale-95 transition-all flex items-center gap-2 text-sm"
          >
            <span>DOWNLOAD HIGH-RES PNG</span>
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
            </svg>
          </button>
        </div>

        <div className="flex-1 relative flex items-center justify-center p-12">
          <div className="w-full h-full max-w-[850px] aspect-square flex items-center justify-center drop-shadow-[0_0_100px_rgba(0,0,0,1)]">
            <WheelCanvas config={config} exportScale={4} onCanvasReady={(c) => { canvasRef.current = c; }} />
          </div>
        </div>

        {/* AI Chat Bar (Docked at bottom) */}
        <div className="p-6 bg-slate-950/80 backdrop-blur-3xl border-t border-white/5 z-40 max-w-4xl mx-auto w-full mb-6 rounded-3xl shadow-2xl flex flex-col gap-4">
           <div className="flex gap-3">
              <input 
                type="text" value={chatInput} onChange={(e) => setChatInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && callAi()}
                placeholder="Ask AI to design a theme (e.g. 'Cyberpunk night city with 12 items')..."
                className="flex-1 bg-white/5 border border-white/10 rounded-2xl px-6 py-4 outline-none focus:border-blue-500 transition-all text-sm font-medium"
              />
              <button onClick={callAi} disabled={isAiLoading} className="px-8 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 text-white rounded-2xl font-black transition-all">
                {isAiLoading ? 'ENGINEERING...' : 'GENERATE'}
              </button>
           </div>

           {chatHistory.length > 1 && (
             <div className="max-h-32 overflow-y-auto pr-2 scrollbar-hide text-xs space-y-3">
               {chatHistory.slice(-1).map((msg, i) => (
                 <div key={i} className="flex flex-col gap-2">
                   <div className="text-slate-400 leading-relaxed italic opacity-80">{msg.content}</div>
                   {msg.items && (
                     <button onClick={() => applyAiItems(msg.items!)} className="self-start text-[10px] bg-blue-500/20 text-blue-400 px-4 py-2 rounded-lg font-black hover:bg-blue-500 hover:text-white transition-all">
                       APPLY SUGGESTED CONTENT ({msg.items.length} SLOTS)
                     </button>
                   )}
                 </div>
               ))}
             </div>
           )}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useEffect, useRef } from 'react';
import { WheelConfig } from '../types';

interface WheelCanvasProps {
  config: WheelConfig;
  exportScale?: number;
  onCanvasReady?: (canvas: HTMLCanvasElement) => void;
}

export const WheelCanvas: React.FC<WheelCanvasProps> = ({ config, exportScale = 2, onCanvasReady }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const drawWheel = (canvas: HTMLCanvasElement, scale: number) => {
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const size = canvas.width;
    const center = size / 2;
    const outerRadius = (size / 2) - (10 * scale); 
    const radius = outerRadius - (config.borderWidth * scale);

    const { items, colorScheme, borderWidth, borderStyle, hubRadius, hubColor, fontSize, fontFamily, fontWeight, fontColor, rotation } = config;

    ctx.clearRect(0, 0, size, size);
    if (items.length === 0) return;

    const sliceAngle = (2 * Math.PI) / items.length;
    const rotationRad = (rotation * Math.PI) / 180;

    // 1. 绘制扇区 (Slices)
    items.forEach((item, i) => {
      const startAngle = i * sliceAngle + rotationRad;
      const endAngle = startAngle + sliceAngle;

      ctx.beginPath();
      ctx.moveTo(center, center);
      ctx.arc(center, center, radius, startAngle, endAngle);
      ctx.closePath();

      ctx.fillStyle = colorScheme.colors[i % colorScheme.colors.length];
      ctx.fill();

      // 扇区边缘柔和分割线
      ctx.lineWidth = 0.8 * scale;
      ctx.strokeStyle = 'rgba(255,255,255,0.1)';
      ctx.stroke();

      if (config.showText) {
        ctx.save();
        ctx.translate(center, center);
        ctx.rotate(startAngle + sliceAngle / 2);
        ctx.textAlign = 'right';
        ctx.textBaseline = 'middle';
        ctx.fillStyle = fontColor;
        ctx.font = `${fontWeight} ${fontSize * scale}px ${fontFamily}`;
        const textRadius = radius - (20 * scale);
        ctx.fillText(item, textRadius, 0, radius * 0.7);
        ctx.restore();
      }
    });

    // 2. 增强型物理质感边框绘制
    if (borderWidth > 0) {
      ctx.save();
      const bRadius = radius + (borderWidth * scale / 2);
      ctx.beginPath();
      ctx.arc(center, center, bRadius, 0, 2 * Math.PI);
      ctx.lineWidth = borderWidth * scale;

      // 预设坐标辅助
      const gradX1 = center - outerRadius, gradY1 = center - outerRadius;
      const gradX2 = center + outerRadius, gradY2 = center + outerRadius;

      switch (borderStyle) {
        case 'titanium': {
          // 航天钛金：使用锥形渐变模拟金属拉丝在旋转时的受光变化
          const g = ctx.createConicGradient(rotationRad, center, center);
          g.addColorStop(0, '#555');
          g.addColorStop(0.2, '#999');
          g.addColorStop(0.25, '#eee'); // 强高光点
          g.addColorStop(0.3, '#999');
          g.addColorStop(0.5, '#555');
          g.addColorStop(0.7, '#999');
          g.addColorStop(0.75, '#eee'); // 对角高光点
          g.addColorStop(0.8, '#999');
          g.addColorStop(1, '#555');
          ctx.strokeStyle = g;
          ctx.stroke();

          // 叠加细腻拉丝纹理
          ctx.lineWidth = 1 * scale;
          ctx.strokeStyle = 'rgba(255,255,255,0.03)';
          for (let r = radius; r < outerRadius; r += 2 * scale) {
            ctx.beginPath();
            ctx.arc(center, center, r, 0, Math.PI * 2);
            ctx.stroke();
          }
          break;
        }
        case 'polished_gold': {
          // 镜面流光金：高对比度的锥形渐变，产生强烈的镜面反射感
          const g = ctx.createConicGradient(rotationRad * 0.5, center, center);
          g.addColorStop(0, '#8e5d0d');
          g.addColorStop(0.15, '#fcf6ba');
          g.addColorStop(0.3, '#b38728');
          g.addColorStop(0.5, '#fbf5b7');
          g.addColorStop(0.65, '#8e5d0d');
          g.addColorStop(0.85, '#fcf6ba');
          g.addColorStop(1, '#8e5d0d');
          ctx.strokeStyle = g;
          ctx.stroke();
          break;
        }
        case 'italian_leather': {
          // 意式皮革：深色基调叠加微小颗粒感，边缘加入明暗阴影
          ctx.strokeStyle = '#3d261a';
          ctx.stroke();
          // 绘制皮革颗粒噪声
          ctx.save();
          ctx.clip();
          ctx.globalAlpha = 0.15;
          for (let i = 0; i < 2000; i++) {
            const r = radius + Math.random() * (outerRadius - radius);
            const a = Math.random() * Math.PI * 2;
            ctx.fillStyle = Math.random() > 0.5 ? '#fff' : '#000';
            ctx.fillRect(center + Math.cos(a) * r, center + Math.sin(a) * r, 1 * scale, 1 * scale);
          }
          ctx.restore();
          // 缝线效果：缝线随转盘旋转
          ctx.beginPath();
          ctx.arc(center, center, radius + 5 * scale, 0, Math.PI * 2);
          ctx.setLineDash([6 * scale, 6 * scale]);
          ctx.lineDashOffset = rotation * scale; 
          ctx.lineWidth = 1.5 * scale;
          ctx.strokeStyle = 'rgba(255,255,255,0.2)';
          ctx.stroke();
          break;
        }
        case 'canvas_fabric': {
          // 帆布织物：交叉网格纹理，旋转时产生莫尔条纹般的质感变化
          ctx.strokeStyle = '#6d5a4a';
          ctx.stroke();
          ctx.save();
          ctx.clip();
          ctx.lineWidth = 0.5 * scale;
          ctx.strokeStyle = 'rgba(0,0,0,0.2)';
          // 经线
          for(let i = -size; i < size*2; i += 3 * scale) {
            ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i + size, size); ctx.stroke();
          }
          // 纬线
          for(let i = -size; i < size*2; i += 3 * scale) {
            ctx.beginPath(); ctx.moveTo(i + size, 0); ctx.lineTo(i, size); ctx.stroke();
          }
          ctx.restore();
          break;
        }
        case 'frosted_glass': {
          // 磨砂玻璃：柔和的多重渐变，中心稍暗，边缘明亮
          const g = ctx.createRadialGradient(center, center, radius, center, center, outerRadius);
          g.addColorStop(0, 'rgba(255,255,255,0.4)');
          g.addColorStop(0.5, 'rgba(255,255,255,0.1)');
          g.addColorStop(1, 'rgba(255,255,255,0.4)');
          ctx.strokeStyle = g;
          ctx.shadowBlur = 10 * scale;
          ctx.shadowColor = 'rgba(255,255,255,0.2)';
          ctx.stroke();
          // 旋转的高光扫射
          const hg = ctx.createConicGradient(rotationRad * 1.2, center, center);
          hg.addColorStop(0, 'transparent');
          hg.addColorStop(0.1, 'rgba(255,255,255,0.3)');
          hg.addColorStop(0.2, 'transparent');
          ctx.strokeStyle = hg;
          ctx.stroke();
          break;
        }
        case 'luxury_silk': {
          // 流光绸缎：极其灵动的色彩流转，使用多重色彩的锥形渐变
          const g = ctx.createConicGradient(rotationRad, center, center);
          g.addColorStop(0, '#7b0000');
          g.addColorStop(0.2, '#ff3b3b');
          g.addColorStop(0.4, '#7b0000');
          g.addColorStop(0.6, '#ff3b3b');
          g.addColorStop(0.8, '#7b0000');
          g.addColorStop(1, '#7b0000');
          ctx.strokeStyle = g;
          ctx.stroke();
          break;
        }
        case 'cyber_neon': {
          // 赛博霓虹：自发光效果，随旋转闪烁的灯带点
          ctx.strokeStyle = '#00f3ff';
          ctx.shadowBlur = 25 * scale;
          ctx.shadowColor = '#00f3ff';
          ctx.stroke();
          // 旋转流光点
          const dots = 16;
          for(let i=0; i<dots; i++){
            const angle = (i * (360/dots) + rotation * 2.5) * Math.PI/180;
            ctx.beginPath();
            ctx.arc(center + Math.cos(angle) * bRadius, center + Math.sin(angle) * bRadius, 3 * scale, 0, Math.PI*2);
            ctx.fillStyle = '#fff';
            ctx.shadowBlur = 10 * scale;
            ctx.shadowColor = '#fff';
            ctx.fill();
          }
          break;
        }
        case 'diamond_cut': {
          // 钻石切割：模拟棱镜折射，不同角度呈现不同光谱色
          ctx.save();
          ctx.clip();
          const facets = 48;
          for(let i=0; i<facets; i++) {
            const a = i * (360/facets) * Math.PI/180;
            const facetGrad = ctx.createLinearGradient(
              center + Math.cos(a) * radius, center + Math.sin(a) * radius,
              center + Math.cos(a) * outerRadius, center + Math.sin(a) * outerRadius
            );
            const hue = (i * 15 + rotation) % 360;
            facetGrad.addColorStop(0, `hsla(${hue}, 80%, 95%, 0.8)`);
            facetGrad.addColorStop(0.5, `hsla(${hue}, 80%, 70%, 0.5)`);
            facetGrad.addColorStop(1, `hsla(${hue}, 80%, 40%, 0.8)`);
            ctx.fillStyle = facetGrad;
            ctx.beginPath();
            ctx.moveTo(center, center);
            ctx.arc(center, center, outerRadius + 10*scale, a, a + (Math.PI*2/facets));
            ctx.fill();
          }
          ctx.restore();
          break;
        }
        case 'industrial_steel': {
          // 工业精钢：冷色调拉丝，带有较重的手工感和磨损
          const g = ctx.createConicGradient(rotationRad * 0.8, center, center);
          g.addColorStop(0, '#222');
          g.addColorStop(0.25, '#888');
          g.addColorStop(0.5, '#444');
          g.addColorStop(0.75, '#aaa');
          g.addColorStop(1, '#222');
          ctx.strokeStyle = g;
          ctx.stroke();
          // 随机划痕
          ctx.save(); ctx.clip();
          ctx.strokeStyle = 'rgba(255,255,255,0.08)';
          ctx.lineWidth = 0.5 * scale;
          for(let i=0; i<100; i++){
            const r1 = radius + Math.random() * (outerRadius - radius);
            const a1 = Math.random() * Math.PI * 2;
            const len = Math.random() * 20 * scale;
            ctx.beginPath();
            ctx.moveTo(center + Math.cos(a1) * r1, center + Math.sin(a1) * r1);
            ctx.lineTo(center + Math.cos(a1) * r1 + len, center + Math.sin(a1) * r1 + len);
            ctx.stroke();
          }
          ctx.restore();
          break;
        }
        default: {
          // 基础兜底质感
          const g = ctx.createConicGradient(rotationRad, center, center);
          g.addColorStop(0, '#333');
          g.addColorStop(0.5, '#666');
          g.addColorStop(1, '#333');
          ctx.strokeStyle = g;
          ctx.stroke();
          break;
        }
      }

      // 全局顶层光照优化 (Ambient occlusion / Rim light)
      const ringLight = ctx.createLinearGradient(gradX1, gradY1, center, center);
      ringLight.addColorStop(0, 'rgba(255,255,255,0.25)');
      ringLight.addColorStop(0.5, 'rgba(255,255,255,0)');
      ringLight.addColorStop(1, 'rgba(0,0,0,0.15)');
      ctx.strokeStyle = ringLight;
      ctx.stroke();

      ctx.restore();
    }

    // 3. 中心轴承 (Depth Hub)
    if (hubRadius > 0) {
      ctx.save();
      ctx.beginPath();
      ctx.arc(center, center, hubRadius * scale, 0, 2 * Math.PI);

      // 轴承高光不随整体旋转，模拟环境光
      const hubGrad = ctx.createRadialGradient(center - hubRadius/2, center - hubRadius/2, 0, center, center, hubRadius * scale);
      hubGrad.addColorStop(0, '#ffffff');
      hubGrad.addColorStop(0.7, hubColor);
      hubGrad.addColorStop(1, '#666');
      ctx.fillStyle = hubGrad;
      ctx.shadowBlur = 15 * scale;
      ctx.shadowColor = 'rgba(0,0,0,0.4)';
      ctx.fill();

      // 内部金属环
      ctx.beginPath();
      ctx.arc(center, center, hubRadius * 0.8 * scale, 0, 2 * Math.PI);
      ctx.strokeStyle = 'rgba(0,0,0,0.1)';
      ctx.lineWidth = 1 * scale;
      ctx.stroke();

      ctx.restore();
    }
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const scale = exportScale;
    const displaySize = 1000; 
    canvas.width = displaySize * scale;
    canvas.height = displaySize * scale;
    drawWheel(canvas, scale);
    if (onCanvasReady) onCanvasReady(canvas);
  }, [config, exportScale]);

  return (
    <div className="w-full h-full flex justify-center items-center bg-transparent p-0 overflow-hidden">
      <canvas 
        ref={canvasRef} 
        className="max-w-full max-h-full object-contain drop-shadow-[0_80px_160px_rgba(0,0,0,0.8)]"
      />
    </div>
  );
};

