import React, { useEffect, useRef } from 'react';
import { WheelConfig } from '../types';

interface WheelCanvasProps {
  config: WheelConfig;
  exportScale?: number;
  onCanvasReady?: (canvas: HTMLCanvasElement) => void;
}

export const WheelCanvas: React.FC<WheelCanvasProps> = ({ config, exportScale = 2, onCanvasReady }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const drawWheel = (canvas: HTMLCanvasElement, scale: number) => {
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const size = canvas.width;
    const center = size / 2;
    const outerRadius = (size / 2) - (10 * scale); 
    const radius = outerRadius - (config.borderWidth * scale);

    const { items, colorScheme, borderWidth, borderStyle, hubRadius, hubColor, fontSize, fontFamily, fontWeight, fontColor, rotation } = config;

    ctx.clearRect(0, 0, size, size);
    if (items.length === 0) return;

    const sliceAngle = (2 * Math.PI) / items.length;
    const rotationRad = (rotation * Math.PI) / 180;

    // 1. 绘制扇区
    items.forEach((item, i) => {
      const startAngle = i * sliceAngle + rotationRad;
      const endAngle = startAngle + sliceAngle;

      ctx.beginPath();
      ctx.moveTo(center, center);
      ctx.arc(center, center, radius, startAngle, endAngle);
      ctx.closePath();

      ctx.fillStyle = colorScheme.colors[i % colorScheme.colors.length];
      ctx.fill();

      ctx.lineWidth = 0.8 * scale;
      ctx.strokeStyle = 'rgba(255,255,255,0.15)';
      ctx.stroke();

      if (config.showText) {
        ctx.save();
        ctx.translate(center, center);
        ctx.rotate(startAngle + sliceAngle / 2);

        ctx.textAlign = 'right';
        ctx.textBaseline = 'middle';
        ctx.fillStyle = fontColor;
        ctx.font = `${fontWeight} ${fontSize * scale}px ${fontFamily}`;

        const textRadius = radius - (20 * scale);
        const maxWidth = radius * 0.75;
        ctx.fillText(item, textRadius, 0, maxWidth);

        ctx.restore();
      }
    });

    // 2. 增强物理质感边框绘制
    if (borderWidth > 0) {
      ctx.save();
      const bRadius = radius + (borderWidth * scale / 2);
      ctx.beginPath();
      ctx.arc(center, center, bRadius, 0, 2 * Math.PI);
      ctx.lineWidth = borderWidth * scale;

      const gradX = center - outerRadius;
      const gradY = center - outerRadius;
      const gradX2 = center + outerRadius;
      const gradY2 = center + outerRadius;

      switch (borderStyle) {
        case 'titanium': {
          // 使用锥形渐变模拟金属旋转时的光影
          const grad = ctx.createConicGradient(rotationRad, center, center);
          grad.addColorStop(0, '#2c3e50');
          grad.addColorStop(0.2, '#7f8c8d');
          grad.addColorStop(0.25, '#bdc3c7'); // 强高光
          grad.addColorStop(0.3, '#7f8c8d');
          grad.addColorStop(0.5, '#2c3e50');
          grad.addColorStop(0.7, '#7f8c8d');
          grad.addColorStop(0.75, '#bdc3c7'); // 对角高光
          grad.addColorStop(0.8, '#7f8c8d');
          grad.addColorStop(1, '#2c3e50');
          ctx.strokeStyle = grad;
          ctx.stroke();

          // 细腻的拉丝纹理 (细环)
          ctx.lineWidth = 0.5 * scale;
          ctx.strokeStyle = 'rgba(255,255,255,0.05)';
          for (let r = radius; r < outerRadius; r += 2 * scale) {
            ctx.beginPath();
            ctx.arc(center, center, r, 0, Math.PI * 2);
            ctx.stroke();
          }
          break;
        }
        case 'polished_gold': {
          const grad = ctx.createConicGradient(rotationRad * 0.5, center, center);
          grad.addColorStop(0, '#8e5d0d');
          grad.addColorStop(0.2, '#fcf6ba');
          grad.addColorStop(0.4, '#b38728');
          grad.addColorStop(0.6, '#fbf5b7');
          grad.addColorStop(0.8, '#b38728');
          grad.addColorStop(1, '#8e5d0d');
          ctx.strokeStyle = grad;
          ctx.stroke();
          break;
        }
        case 'carbon_fiber': {
          ctx.strokeStyle = '#111';
          ctx.stroke();
          // 编织图案剪裁
          ctx.save();
          ctx.clip();
          ctx.lineWidth = 1 * scale;
          ctx.strokeStyle = 'rgba(255,255,255,0.05)';
          for (let k = -size; k < size * 2; k += 4 * scale) {
            ctx.beginPath(); ctx.moveTo(k, 0); ctx.lineTo(k + size, size); ctx.stroke();
          }
          ctx.strokeStyle = 'rgba(0,0,0,0.3)';
          for (let k = -size; k < size * 2; k += 4 * scale) {
            ctx.beginPath(); ctx.moveTo(k + 2 * scale, 0); ctx.lineTo(k + size + 2 * scale, size); ctx.stroke();
          }
          ctx.restore();
          break;
        }
        case 'italian_leather': {
          ctx.strokeStyle = '#3d261b';
          ctx.stroke();
          // 绘制细微皮纹噪声
          ctx.save();
          ctx.clip();
          ctx.globalAlpha = 0.1;
          for (let i = 0; i < 1500; i++) {
            const rx = center + (Math.random() - 0.5) * outerRadius * 2;
            const ry = center + (Math.random() - 0.5) * outerRadius * 2;
            ctx.fillStyle = Math.random() > 0.5 ? '#fff' : '#000';
            ctx.fillRect(rx, ry, 1 * scale, 1 * scale);
          }
          ctx.restore();
          // 缝线效果：随旋转变化的虚线
          ctx.beginPath();
          ctx.arc(center, center, radius + 5 * scale, 0, Math.PI * 2);
          ctx.setLineDash([5 * scale, 5 * scale]);
          ctx.lineDashOffset = rotation * scale;
          ctx.lineWidth = 1.5 * scale;
          ctx.strokeStyle = 'rgba(255,255,255,0.2)';
          ctx.stroke();
          break;
        }
        case 'frosted_glass': {
          const grad = ctx.createRadialGradient(center, center, radius, center, center, outerRadius);
          grad.addColorStop(0, 'rgba(255,255,255,0.4)');
          grad.addColorStop(0.5, 'rgba(255,255,255,0.1)');
          grad.addColorStop(1, 'rgba(255,255,255,0.4)');
          ctx.strokeStyle = grad;
          ctx.shadowBlur = 10 * scale;
          ctx.shadowColor = 'rgba(255,255,255,0.2)';
          ctx.stroke();
          // 旋转高光
          const shine = ctx.createConicGradient(rotationRad * 1.5, center, center);
          shine.addColorStop(0, 'transparent');
          shine.addColorStop(0.1, 'rgba(255,255,255,0.3)');
          shine.addColorStop(0.2, 'transparent');
          ctx.strokeStyle = shine;
          ctx.stroke();
          break;
        }
        case 'luxury_silk': {
          const grad = ctx.createConicGradient(rotationRad, center, center);
          grad.addColorStop(0, '#c0392b');
          grad.addColorStop(0.2, '#e74c3c');
          grad.addColorStop(0.4, '#c0392b');
          grad.addColorStop(0.6, '#e74c3c');
          grad.addColorStop(0.8, '#c0392b');
          grad.addColorStop(1, '#c0392b');
          ctx.strokeStyle = grad;
          ctx.stroke();
          break;
        }
        case 'cyber_neon': {
          ctx.strokeStyle = '#00f3ff';
          ctx.shadowBlur = 20 * scale;
          ctx.shadowColor = '#00f3ff';
          ctx.stroke();
          // 旋转的光点灯带
          const dots = 12;
          for (let i = 0; i < dots; i++) {
            const angle = (i * (360 / dots) + rotation * 2) * Math.PI / 180;
            ctx.beginPath();
            ctx.arc(center + Math.cos(angle) * bRadius, center + Math.sin(angle) * bRadius, 3 * scale, 0, Math.PI * 2);
            ctx.fillStyle = '#fff';
            ctx.fill();
          }
          break;
        }
        case 'diamond_cut': {
          ctx.strokeStyle = '#fff';
          ctx.stroke();
          ctx.save(); ctx.clip();
          const facets = 36;
          for (let i = 0; i < facets; i++) {
            const a = i * (360 / facets) * Math.PI / 180;
            const hue = (i * 20 + rotation) % 360;
            ctx.fillStyle = `hsla(${hue}, 70%, 70%, 0.4)`;
            ctx.beginPath();
            ctx.moveTo(center, center);
            ctx.arc(center, center, outerRadius + 10 * scale, a, a + (Math.PI * 2 / facets));
            ctx.fill();
          }
          ctx.restore();
          break;
        }
        case 'canvas_fabric': {
          ctx.strokeStyle = '#6d5a4a';
          ctx.stroke();
          ctx.save(); ctx.clip();
          ctx.lineWidth = 0.5 * scale;
          ctx.strokeStyle = 'rgba(0,0,0,0.2)';
          // 织物经纬线
          for (let i = -size; i < size * 2; i += 3 * scale) {
            ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i + size, size); ctx.stroke();
            ctx.beginPath(); ctx.moveTo(i + size, 0); ctx.lineTo(i, size); ctx.stroke();
          }
          ctx.restore();
          break;
        }
        case 'pearl_essence': {
          const grad = ctx.createConicGradient(rotationRad * 0.7, center, center);
          grad.addColorStop(0, '#efd5ff');
          grad.addColorStop(0.3, '#d5f3ff');
          grad.addColorStop(0.6, '#ffd5d5');
          grad.addColorStop(1, '#efd5ff');
          ctx.strokeStyle = grad;
          ctx.stroke();
          break;
        }
        case 'white_marble': {
          ctx.strokeStyle = '#f5f5f5';
          ctx.stroke();
          ctx.save(); ctx.clip();
          // 绘制大理石纹路
          ctx.lineWidth = 1 * scale;
          ctx.strokeStyle = 'rgba(0,0,0,0.1)';
          for (let i = 0; i < 20; i++) {
            ctx.beginPath();
            let x = Math.random() * size, y = 0;
            ctx.moveTo(x, y);
            for (let j = 0; j < 10; j++) {
              x += (Math.random() - 0.5) * 50 * scale;
              y += (size / 10);
              ctx.lineTo(x, y);
            }
            ctx.stroke();
          }
          ctx.restore();
          break;
        }
        case 'natural_wood': {
          ctx.strokeStyle = '#3d2b1f';
          ctx.stroke();
          ctx.save(); ctx.clip();
          ctx.lineWidth = 1 * scale;
          ctx.strokeStyle = 'rgba(0,0,0,0.2)';
          // 年轮纹理
          for (let r = radius; r < outerRadius; r += 4 * scale) {
            const ox = (Math.random() - 0.5) * 2 * scale;
            ctx.beginPath();
            ctx.arc(center + ox, center + ox, r, 0, Math.PI * 2);
            ctx.stroke();
          }
          ctx.restore();
          break;
        }
        case 'industrial_steel': {
          const grad = ctx.createLinearGradient(gradX, gradY, gradX2, gradY2);
          grad.addColorStop(0, '#444');
          grad.addColorStop(0.5, '#aaa');
          grad.addColorStop(1, '#444');
          ctx.strokeStyle = grad;
          ctx.stroke();
          // 垂直划痕
          ctx.save(); ctx.clip();
          ctx.lineWidth = 0.5 * scale;
          ctx.strokeStyle = 'rgba(255,255,255,0.1)';
          for (let i = 0; i < size; i += 2 * scale) {
            ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i, size); ctx.stroke();
          }
          ctx.restore();
          break;
        }
        default:
          ctx.strokeStyle = config.borderColor;
          if (borderStyle === 'dotted') ctx.setLineDash([4 * scale, 8 * scale]);
          ctx.stroke();
          break;
      }

      // 全局受光效果 (Ambient Occlusion)
      const aoGrad = ctx.createLinearGradient(gradX, gradY, center, center);
      aoGrad.addColorStop(0, 'rgba(255,255,255,0.2)');
      aoGrad.addColorStop(1, 'rgba(0,0,0,0.1)');
      ctx.strokeStyle = aoGrad;
      ctx.stroke();

      ctx.restore();
    }

    // 3. 中心轴承
    if (hubRadius > 0) {
      ctx.save();
      ctx.beginPath();
      ctx.arc(center, center, hubRadius * scale, 0, 2 * Math.PI);

      const hubGrad = ctx.createRadialGradient(center - hubRadius/3, center - hubRadius/3, 0, center, center, hubRadius * scale);
      hubGrad.addColorStop(0, '#fff');
      hubGrad.addColorStop(0.7, hubColor);
      hubGrad.addColorStop(1, '#999');
      ctx.fillStyle = hubGrad;
      ctx.shadowBlur = 10 * scale;
      ctx.shadowColor = 'rgba(0,0,0,0.3)';
      ctx.fill();

      ctx.lineWidth = 1 * scale;
      ctx.strokeStyle = 'rgba(0,0,0,0.1)';
      ctx.stroke();
      ctx.restore();
    }
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const scale = exportScale;
    const displaySize = 1000; 
    canvas.width = displaySize * scale;
    canvas.height = displaySize * scale;
    canvas.style.width = `100%`;
    canvas.style.height = `100%`;

    drawWheel(canvas, scale);
    if (onCanvasReady) onCanvasReady(canvas);
  }, [config, exportScale]);

  return (
    <div className="w-full h-full flex justify-center items-center bg-transparent p-0 overflow-hidden">
      <canvas 
        ref={canvasRef} 
        className="max-w-full max-h-full object-contain drop-shadow-[0_60px_120px_rgba(0,0,0,0.7)]"
      />
    </div>
  );
};

import React, { useEffect, useRef } from 'react';
import { WheelConfig } from '../types';

interface WheelCanvasProps {
  config: WheelConfig;
  exportScale?: number;
  onCanvasReady?: (canvas: HTMLCanvasElement) => void;
}

export const WheelCanvas: React.FC<WheelCanvasProps> = ({ config, exportScale = 2, onCanvasReady }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const drawWheel = (canvas: HTMLCanvasElement, scale: number) => {
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const size = canvas.width;
    const center = size / 2;
    const outerRadius = (size / 2) - (15 * scale); 
    const radius = outerRadius - (config.borderWidth * scale);

    const { items, colorScheme, borderWidth, borderStyle, hubRadius, hubColor, fontSize, fontFamily, fontWeight, fontColor, rotation } = config;

    ctx.clearRect(0, 0, size, size);
    if (items.length === 0) return;

    const sliceAngle = (2 * Math.PI) / items.length;
    const rotationRad = (rotation * Math.PI) / 180;

    // 1. 绘制扇区
    items.forEach((item, i) => {
      const startAngle = i * sliceAngle + rotationRad;
      const endAngle = startAngle + sliceAngle;

      ctx.beginPath();
      ctx.moveTo(center, center);
      ctx.arc(center, center, radius, startAngle, endAngle);
      ctx.closePath();

      ctx.fillStyle = colorScheme.colors[i % colorScheme.colors.length];
      ctx.fill();

      ctx.lineWidth = 1 * scale;
      ctx.strokeStyle = 'rgba(255,255,255,0.2)';
      ctx.stroke();

      if (config.showText) {
        ctx.save();
        ctx.translate(center, center);
        ctx.rotate(startAngle + sliceAngle / 2);

        ctx.textAlign = 'right';
        ctx.textBaseline = 'middle';
        ctx.fillStyle = fontColor;
        ctx.font = `${fontWeight} ${fontSize * scale}px ${fontFamily}`;

        const textRadius = radius - (25 * scale);
        const maxWidth = radius * 0.75;
        ctx.fillText(item, textRadius, 0, maxWidth);

        ctx.restore();
      }
    });

    // 2. 增强物理质感边框绘制
    if (borderWidth > 0) {
      ctx.save();
      const bRadius = radius + (borderWidth * scale / 2);
      ctx.beginPath();
      ctx.arc(center, center, bRadius, 0, 2 * Math.PI);
      ctx.lineWidth = borderWidth * scale;

      const gradX1 = center - outerRadius, gradY1 = center - outerRadius;
      const gradX2 = center + outerRadius, gradY2 = center + outerRadius;

      switch (borderStyle) {
        case 'titanium': {
          // 强化拉丝钛金：极高的明暗对比产生强烈的转动流光感
          const grad = ctx.createConicGradient(rotationRad, center, center);
          grad.addColorStop(0, '#333');
          grad.addColorStop(0.2, '#666');
          grad.addColorStop(0.25, '#fff'); // 锐利高光
          grad.addColorStop(0.3, '#666');
          grad.addColorStop(0.5, '#222');
          grad.addColorStop(0.7, '#666');
          grad.addColorStop(0.75, '#fff'); // 对角锐利高光
          grad.addColorStop(0.8, '#666');
          grad.addColorStop(1, '#333');
          ctx.strokeStyle = grad;
          ctx.stroke();

          ctx.lineWidth = 0.5 * scale;
          ctx.strokeStyle = 'rgba(255,255,255,0.08)';
          for (let r = radius; r < outerRadius; r += 2 * scale) {
            ctx.beginPath(); ctx.arc(center, center, r, 0, Math.PI * 2); ctx.stroke();
          }
          break;
        }
        case 'polished_gold': {
          const grad = ctx.createConicGradient(rotationRad * 0.8, center, center);
          grad.addColorStop(0, '#6d4c11');
          grad.addColorStop(0.1, '#fcf6ba');
          grad.addColorStop(0.2, '#b38728');
          grad.addColorStop(0.5, '#fbf5b7');
          grad.addColorStop(0.8, '#b38728');
          grad.addColorStop(0.9, '#fcf6ba');
          grad.addColorStop(1, '#6d4c11');
          ctx.strokeStyle = grad;
          ctx.stroke();
          break;
        }
        case 'italian_leather': {
          ctx.strokeStyle = '#2b1a14';
          ctx.stroke();
          ctx.save(); ctx.clip();
          // 增加皮革表面的漫反射高光，随旋转微变
          const leatherGrad = ctx.createConicGradient(rotationRad, center, center);
          leatherGrad.addColorStop(0, 'rgba(0,0,0,0.2)');
          leatherGrad.addColorStop(0.25, 'rgba(255,255,255,0.05)');
          leatherGrad.addColorStop(0.5, 'rgba(0,0,0,0.2)');
          leatherGrad.addColorStop(0.75, 'rgba(255,255,255,0.05)');
          ctx.fillStyle = leatherGrad;
          ctx.fillRect(gradX1, gradY1, outerRadius*2, outerRadius*2);

          ctx.globalAlpha = 0.15;
          for (let i = 0; i < 1000; i++) {
            const rx = center + (Math.random() - 0.5) * outerRadius * 2;
            const ry = center + (Math.random() - 0.5) * outerRadius * 2;
            ctx.fillStyle = Math.random() > 0.5 ? '#fff' : '#000';
            ctx.fillRect(rx, ry, 1.2 * scale, 1.2 * scale);
          }
          ctx.restore();
          break;
        }
        case 'frosted_glass': {
          const grad = ctx.createRadialGradient(center, center, radius, center, center, outerRadius);
          grad.addColorStop(0, 'rgba(240,240,240,0.8)');
          grad.addColorStop(0.5, 'rgba(255,255,255,0.3)');
          grad.addColorStop(1, 'rgba(220,220,220,0.6)');
          ctx.strokeStyle = grad;
          ctx.shadowBlur = 15 * scale;
          ctx.shadowColor = 'rgba(0,0,0,0.05)';
          ctx.stroke();
          // 强对比度的旋转扫掠光
          const shine = ctx.createConicGradient(rotationRad * 1.2, center, center);
          shine.addColorStop(0, 'transparent');
          shine.addColorStop(0.1, 'rgba(255,255,255,0.6)');
          shine.addColorStop(0.15, 'rgba(255,255,255,0.9)');
          shine.addColorStop(0.2, 'rgba(255,255,255,0.6)');
          shine.addColorStop(0.3, 'transparent');
          ctx.strokeStyle = shine;
          ctx.stroke();
          break;
        }
        case 'luxury_silk': {
          const grad = ctx.createConicGradient(rotationRad, center, center);
          grad.addColorStop(0, '#5e0000');
          grad.addColorStop(0.2, '#c0392b');
          grad.addColorStop(0.25, '#ff7675'); // 丝绸折射光
          grad.addColorStop(0.3, '#c0392b');
          grad.addColorStop(0.5, '#5e0000');
          grad.addColorStop(0.7, '#c0392b');
          grad.addColorStop(0.75, '#ff7675');
          grad.addColorStop(0.8, '#c0392b');
          grad.addColorStop(1, '#5e0000');
          ctx.strokeStyle = grad;
          ctx.stroke();
          break;
        }
        case 'cyber_neon': {
          ctx.strokeStyle = '#00d2ff';
          ctx.shadowBlur = 30 * scale;
          ctx.shadowColor = 'rgba(0, 210, 255, 0.6)';
          ctx.stroke();
          const dots = 18;
          for (let i = 0; i < dots; i++) {
            const angle = (i * (360 / dots) + rotation * 3) * Math.PI / 180;
            ctx.beginPath();
            ctx.arc(center + Math.cos(angle) * bRadius, center + Math.sin(angle) * bRadius, 4 * scale, 0, Math.PI * 2);
            ctx.fillStyle = '#fff';
            ctx.shadowBlur = 10 * scale;
            ctx.shadowColor = '#00f3ff';
            ctx.fill();
          }
          break;
        }
        case 'canvas_fabric': {
          ctx.strokeStyle = '#5d4037';
          ctx.stroke();
          ctx.save(); ctx.clip();
          // 织物在光照下的旋转阴影
          const fabricShade = ctx.createConicGradient(rotationRad, center, center);
          fabricShade.addColorStop(0, 'rgba(0,0,0,0.1)');
          fabricShade.addColorStop(0.5, 'rgba(255,255,255,0.05)');
          fabricShade.addColorStop(1, 'rgba(0,0,0,0.1)');
          ctx.fillStyle = fabricShade;
          ctx.fillRect(gradX1, gradY1, outerRadius*2, outerRadius*2);

          ctx.lineWidth = 0.6 * scale;
          ctx.strokeStyle = 'rgba(0,0,0,0.15)';
          for (let i = -size; i < size * 2; i += 4 * scale) {
            ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i + size, size); ctx.stroke();
            ctx.beginPath(); ctx.moveTo(i + size, 0); ctx.lineTo(i, size); ctx.stroke();
          }
          ctx.restore();
          break;
        }
        case 'diamond_cut': {
          ctx.strokeStyle = 'rgba(255,255,255,0.8)';
          ctx.stroke();
          ctx.save(); ctx.clip();
          const facets = 60;
          for (let i = 0; i < facets; i++) {
            const a = i * (360 / facets) * Math.PI / 180;
            const hue = (i * 24 + rotation * 2) % 360;
            const grad = ctx.createLinearGradient(center, center, center + Math.cos(a)*outerRadius, center + Math.sin(a)*outerRadius);
            grad.addColorStop(0.7, `hsla(${hue}, 80%, 80%, 0)`);
            grad.addColorStop(1, `hsla(${hue}, 90%, 70%, 0.6)`);
            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(center, center);
            ctx.arc(center, center, outerRadius + 10 * scale, a, a + (Math.PI * 2 / facets));
            ctx.fill();
          }
          ctx.restore();
          break;
        }
        default:
          ctx.strokeStyle = config.borderColor;
          if (borderStyle === 'dotted') ctx.setLineDash([4 * scale, 8 * scale]);
          ctx.stroke();
          break;
      }

      // 顶层环境光效果 (Rim Light) - 在白色背景下增加可见度
      const rimGrad = ctx.createLinearGradient(gradX1, gradY1, gradX2, gradY2);
      rimGrad.addColorStop(0, 'rgba(255,255,255,0.4)');
      rimGrad.addColorStop(0.5, 'rgba(255,255,255,0)');
      rimGrad.addColorStop(1, 'rgba(0,0,0,0.05)');
      ctx.strokeStyle = rimGrad;
      ctx.stroke();

      ctx.restore();
    }

    // 3. 中心轴承
    if (hubRadius > 0) {
      ctx.save();
      ctx.beginPath();
      ctx.arc(center, center, hubRadius * scale, 0, 2 * Math.PI);

      const hubGrad = ctx.createRadialGradient(center - hubRadius/3, center - hubRadius/3, 0, center, center, hubRadius * scale);
      hubGrad.addColorStop(0, '#fff');
      hubGrad.addColorStop(0.7, hubColor);
      hubGrad.addColorStop(1, '#777');
      ctx.fillStyle = hubGrad;
      ctx.shadowBlur = 20 * scale;
      ctx.shadowColor = 'rgba(0,0,0,0.2)';
      ctx.fill();

      ctx.lineWidth = 1 * scale;
      ctx.strokeStyle = 'rgba(0,0,0,0.05)';
      ctx.stroke();
      ctx.restore();
    }
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const scale = exportScale;
    const displaySize = 1000; 
    canvas.width = displaySize * scale;
    canvas.height = displaySize * scale;
    canvas.style.width = `100%`;
    canvas.style.height = `100%`;

    drawWheel(canvas, scale);
    if (onCanvasReady) onCanvasReady(canvas);
  }, [config, exportScale]);

  return (
    <div className="w-full h-full flex justify-center items-center bg-transparent p-0 overflow-hidden">
      <canvas 
        ref={canvasRef} 
        className="max-w-full max-h-full object-contain drop-shadow-[0_40px_80px_rgba(0,0,0,0.15)]"
      />
    </div>
  );
};

