import React, { useEffect, useRef } from 'react';
import { WheelConfig } from '../types';

interface WheelCanvasProps {
  config: WheelConfig;
  exportScale?: number;
  onCanvasReady?: (canvas: HTMLCanvasElement) => void;
}

export const WheelCanvas: React.FC<WheelCanvasProps> = ({ config, exportScale = 2, onCanvasReady }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const drawWheel = (canvas: HTMLCanvasElement, scale: number) => {
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const size = canvas.width;
    const center = size / 2;
    const outerRadius = (size / 2) - (15 * scale); // 留出一点阴影空间
    const radius = outerRadius - (config.borderWidth * scale);

    const { items, colorScheme, borderWidth, borderStyle, hubRadius, hubColor, fontSize, fontFamily, fontWeight, fontColor, rotation } = config;

    // 清除画布，保持透明背景
    ctx.clearRect(0, 0, size, size);
    if (items.length === 0) return;

    const sliceAngle = (2 * Math.PI) / items.length;
    const rotationRad = (rotation * Math.PI) / 180;

    // 1. 绘制扇区 (Slices)
    items.forEach((item, i) => {
      const startAngle = i * sliceAngle + rotationRad;
      const endAngle = startAngle + sliceAngle;

      ctx.beginPath();
      ctx.moveTo(center, center);
      ctx.arc(center, center, radius, startAngle, endAngle);
      ctx.closePath();

      ctx.fillStyle = colorScheme.colors[i % colorScheme.colors.length];
      ctx.fill();

      // 扇区间的极细分割线，增强结构感
      ctx.lineWidth = 0.5 * scale;
      ctx.strokeStyle = 'rgba(255,255,255,0.15)';
      ctx.stroke();

      if (config.showText) {
        ctx.save();
        ctx.translate(center, center);
        ctx.rotate(startAngle + sliceAngle / 2);

        ctx.textAlign = 'right';
        ctx.textBaseline = 'middle';
        ctx.fillStyle = fontColor;
        ctx.font = `${fontWeight} ${fontSize * scale}px ${fontFamily}`;

        const textRadius = radius - (25 * scale);
        const maxWidth = radius * 0.75;
        ctx.fillText(item, textRadius, 0, maxWidth);

        ctx.restore();
      }
    });

    // 2. 物理质感边框 (Physical Texture Border)
    if (borderWidth > 0) {
      ctx.save();
      const bRadius = radius + (borderWidth * scale / 2);
      ctx.beginPath();
      ctx.arc(center, center, bRadius, 0, 2 * Math.PI);
      ctx.lineWidth = borderWidth * scale;

      const gradX1 = center - outerRadius, gradY1 = center - outerRadius;
      const gradX2 = center + outerRadius, gradY2 = center + outerRadius;

      switch (borderStyle) {
        case 'titanium': {
          // 航天钛金：各向异性金属光泽
          const g = ctx.createConicGradient(rotationRad, center, center);
          g.addColorStop(0, '#2c3e50');
          g.addColorStop(0.2, '#7f8c8d');
          g.addColorStop(0.25, '#ffffff'); // 锐利高光
          g.addColorStop(0.3, '#7f8c8d');
          g.addColorStop(0.5, '#2c3e50');
          g.addColorStop(0.7, '#7f8c8d');
          g.addColorStop(0.75, '#ffffff');
          g.addColorStop(0.8, '#7f8c8d');
          g.addColorStop(1, '#2c3e50');
          ctx.strokeStyle = g;
          ctx.stroke();

          // 环形拉丝细纹
          ctx.lineWidth = 0.5 * scale;
          ctx.strokeStyle = 'rgba(255,255,255,0.06)';
          for (let r = radius; r < outerRadius; r += 2 * scale) {
            ctx.beginPath(); ctx.arc(center, center, r, 0, Math.PI * 2); ctx.stroke();
          }
          break;
        }
        case 'polished_gold': {
          // 镜面流光金：高对比度光泽
          const g = ctx.createConicGradient(rotationRad * 0.5, center, center);
          g.addColorStop(0, '#6d4c11');
          g.addColorStop(0.1, '#fcf6ba');
          g.addColorStop(0.2, '#b38728');
          g.addColorStop(0.5, '#fbf5b7');
          g.addColorStop(0.8, '#b38728');
          g.addColorStop(0.9, '#fcf6ba');
          g.addColorStop(1, '#6d4c11');
          ctx.strokeStyle = g;
          ctx.stroke();
          break;
        }
        case 'carbon_fiber': {
          // 3D 碳纤维：编织纹理
          ctx.strokeStyle = '#0a0a0a';
          ctx.stroke();
          ctx.save(); ctx.clip();
          ctx.lineWidth = 1 * scale;
          ctx.strokeStyle = 'rgba(255,255,255,0.03)';
          for (let k = -size; k < size * 2; k += 4 * scale) {
            ctx.beginPath(); ctx.moveTo(k, 0); ctx.lineTo(k + size, size); ctx.stroke();
          }
          ctx.strokeStyle = 'rgba(0,0,0,0.5)';
          for (let k = -size; k < size * 2; k += 4 * scale) {
            ctx.beginPath(); ctx.moveTo(k + 2 * scale, 0); ctx.lineTo(k + size + 2 * scale, size); ctx.stroke();
          }
          ctx.restore();
          break;
        }
        case 'italian_leather': {
          // 意式皮革：颗粒感与漫反射
          ctx.strokeStyle = '#2b1a14';
          ctx.stroke();
          ctx.save(); ctx.clip();
          ctx.globalAlpha = 0.12;
          for (let i = 0; i < 1200; i++) {
            const rx = center + (Math.random() - 0.5) * outerRadius * 2;
            const ry = center + (Math.random() - 0.5) * outerRadius * 2;
            ctx.fillStyle = Math.random() > 0.5 ? '#fff' : '#000';
            ctx.fillRect(rx, ry, 1.2 * scale, 1.2 * scale);
          }
          ctx.restore();
          break;
        }
        case 'frosted_glass': {
          // 磨砂玻璃：柔和光感与转动扫掠
          const g = ctx.createRadialGradient(center, center, radius, center, center, outerRadius);
          g.addColorStop(0, 'rgba(240,240,240,0.7)');
          g.addColorStop(0.5, 'rgba(255,255,255,0.2)');
          g.addColorStop(1, 'rgba(200,200,200,0.5)');
          ctx.strokeStyle = g;
          ctx.stroke();
          const shine = ctx.createConicGradient(rotationRad * 1.5, center, center);
          shine.addColorStop(0, 'transparent');
          shine.addColorStop(0.1, 'rgba(255,255,255,0.7)');
          shine.addColorStop(0.2, 'transparent');
          ctx.strokeStyle = shine;
          ctx.stroke();
          break;
        }
        case 'canvas_fabric': {
          // 粗粝帆布：网格纤维
          ctx.strokeStyle = '#5d4037';
          ctx.stroke();
          ctx.save(); ctx.clip();
          ctx.lineWidth = 0.8 * scale;
          ctx.strokeStyle = 'rgba(0,0,0,0.15)';
          for (let i = -size; i < size * 2; i += 5 * scale) {
            ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i + size, size); ctx.stroke();
            ctx.beginPath(); ctx.moveTo(i + size, 0); ctx.lineTo(i, size); ctx.stroke();
          }
          ctx.restore();
          break;
        }
        case 'luxury_silk': {
          // 流光绸缎：如丝般顺滑的颜色偏移
          const g = ctx.createConicGradient(rotationRad, center, center);
          g.addColorStop(0, '#5e0000');
          g.addColorStop(0.2, '#c0392b');
          g.addColorStop(0.25, '#ff7979'); // 丝绸亮部
          g.addColorStop(0.3, '#c0392b');
          g.addColorStop(0.5, '#5e0000');
          g.addColorStop(0.75, '#ff7979');
          g.addColorStop(1, '#5e0000');
          ctx.strokeStyle = g;
          ctx.stroke();
          break;
        }
        case 'cyber_neon': {
          // 赛博霓虹：自发光与流光点
          ctx.strokeStyle = '#00d2ff';
          ctx.shadowBlur = 20 * scale;
          ctx.shadowColor = 'rgba(0, 210, 255, 0.6)';
          ctx.stroke();
          const dots = 20;
          for (let i = 0; i < dots; i++) {
            const angle = (i * (360 / dots) + rotation * 4) * Math.PI / 180;
            ctx.beginPath();
            ctx.arc(center + Math.cos(angle) * bRadius, center + Math.sin(angle) * bRadius, 4 * scale, 0, Math.PI * 2);
            ctx.fillStyle = '#fff';
            ctx.shadowBlur = 10 * scale;
            ctx.shadowColor = '#00f3ff';
            ctx.fill();
          }
          break;
        }
        case 'diamond_cut': {
          // 钻石切割：光谱折射
          ctx.save(); ctx.clip();
          const facets = 48;
          for (let i = 0; i < facets; i++) {
            const a = i * (360 / facets) * Math.PI / 180;
            const hue = (i * 20 + rotation * 2) % 360;
            const grad = ctx.createLinearGradient(center, center, center + Math.cos(a)*outerRadius, center + Math.sin(a)*outerRadius);
            grad.addColorStop(0.8, 'rgba(255,255,255,0)');
            grad.addColorStop(1, `hsla(${hue}, 90%, 75%, 0.7)`);
            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(center, center);
            ctx.arc(center, center, outerRadius + 10 * scale, a, a + (Math.PI * 2 / facets));
            ctx.fill();
          }
          ctx.restore();
          break;
        }
        default:
          ctx.strokeStyle = config.borderColor;
          if (borderStyle === 'dotted') ctx.setLineDash([4 * scale, 8 * scale]);
          ctx.stroke();
          break;
      }

      // 边缘高光微调 (Environment Rim Light)
      const rimGrad = ctx.createLinearGradient(gradX1, gradY1, gradX2, gradY2);
      rimGrad.addColorStop(0, 'rgba(255,255,255,0.4)');
      rimGrad.addColorStop(0.5, 'rgba(255,255,255,0)');
      rimGrad.addColorStop(1, 'rgba(0,0,0,0.1)');
      ctx.strokeStyle = rimGrad;
      ctx.stroke();

      ctx.restore();
    }

    // 3. 中央轴承 (Hub)
    if (hubRadius > 0) {
      ctx.save();
      ctx.beginPath();
      ctx.arc(center, center, hubRadius * scale, 0, 2 * Math.PI);

      const hubGrad = ctx.createRadialGradient(center - hubRadius/3, center - hubRadius/3, 0, center, center, hubRadius * scale);
      hubGrad.addColorStop(0, '#fff');
      hubGrad.addColorStop(0.7, hubColor);
      hubGrad.addColorStop(1, '#666');
      ctx.fillStyle = hubGrad;
      ctx.shadowBlur = 20 * scale;
      ctx.shadowColor = 'rgba(0,0,0,0.15)';
      ctx.fill();

      ctx.lineWidth = 1 * scale;
      ctx.strokeStyle = 'rgba(0,0,0,0.05)';
      ctx.stroke();
      ctx.restore();
    }
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const scale = exportScale;
    const displaySize = 1000; 
    canvas.width = displaySize * scale;
    canvas.height = displaySize * scale;
    canvas.style.width = `100%`;
    canvas.style.height = `100%`;

    drawWheel(canvas, scale);
    if (onCanvasReady) onCanvasReady(canvas);
  }, [config, exportScale]);

  return (
    <div className="w-full h-full flex justify-center items-center bg-transparent p-0 overflow-hidden">
      <canvas 
        ref={canvasRef} 
        className="max-w-full max-h-full object-contain drop-shadow-[0_40px_80px_rgba(0,0,0,0.1)]"
      />
    </div>
  );
};

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { WheelCanvas } from './components/WheelCanvas';
import { COLOR_SCHEMES, DEFAULT_CONFIG, CHINESE_FONTS, APP_VERSION, BORDER_STYLES } from './constants';
import { WheelConfig, ColorScheme, BorderStyle } from './types';
import { GoogleGenAI } from "@google/genai";

const App: React.FC = () => {
  const [config, setConfig] = useState<WheelConfig>(DEFAULT_CONFIG);
  const [textInput, setTextInput] = useState(DEFAULT_CONFIG.items.join('\n'));
  const canvasRef = useRef<HTMLCanvasElement | null>(null);

  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<{ role: 'user' | 'ai', content: string, items?: string[] }[]>([
    { role: 'ai', content: `嗨！我是你的灵感助手。请输入你想要的主题和数量，我会为你策划。背景已切换为明亮模式，以便你观察边框质感！` }
  ]);
  const [isAiLoading, setIsAiLoading] = useState(false);

  const handleTextChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const value = e.target.value;
    setTextInput(value);
    const items = value.split('\n').filter(line => line.trim() !== '');
    setConfig(prev => ({ ...prev, items }));
  };

  const updateConfig = (updates: Partial<WheelConfig>) => {
    setConfig(prev => ({ ...prev, ...updates }));
  };

  const downloadImage = () => {
    if (!canvasRef.current) return;
    const link = document.createElement('a');
    link.download = `wheel-pro-render-${Date.now()}.png`;
    link.href = canvasRef.current.toDataURL('image/png', 1.0);
    link.click();
  };

  const callAi = async () => {
    if (!chatInput.trim() || isAiLoading) return;
    const userMsg = chatInput;
    setChatInput('');
    setChatHistory(prev => [...prev, { role: 'user', content: userMsg }]);
    setIsAiLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `用户需求: ${userMsg}. 
        请生成一个适合转盘的文案列表。不要包含序号，每行一个。`,
        config: {
          systemInstruction: "你是一个专业的转盘文案策划。你的目标是根据用户需求提供高质量、有趣、简洁的选项列表。"
        }
      });

      const aiText = response.text || '';
      const lines = aiText.split('\n');
      const detectedItems = lines
        .map(l => l.replace(/^[-*•\d.]+\s*/, '').trim())
        .filter(l => l.length > 0 && l.length < 50);

      setChatHistory(prev => [...prev, { 
        role: 'ai', 
        content: aiText,
        items: detectedItems.length > 0 ? detectedItems : undefined 
      }]);
    } catch (error) {
      setChatHistory(prev => [...prev, { role: 'ai', content: '连接超时，请重试。' }]);
    } finally {
      setIsAiLoading(false);
    }
  };

  const applyAiItems = (items: string[]) => {
    const text = items.join('\n');
    setTextInput(text);
    setConfig(prev => ({ ...prev, items }));
  };

  const inputBaseClass = "w-full bg-slate-800 text-white border border-slate-700 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm transition-all";

  return (
    <div className="flex flex-col md:flex-row h-screen overflow-hidden bg-slate-900 text-slate-100 font-sans">

      {/* 第一列：控制台 */}
      <div className="w-full md:w-80 bg-slate-950 border-r border-white/5 overflow-y-auto p-5 flex flex-col gap-6 shadow-2xl z-20">
        <header>
          <h1 className="text-xl font-black text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-indigo-400">转盘工厂 PRO</h1>
          <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest mt-0.5">Physical Render Engine</p>
        </header>

        <section className="space-y-4">
          <h2 className="text-xs font-bold text-slate-500 uppercase border-b border-white/5 pb-2">内容配置</h2>
          <textarea
            className={`${inputBaseClass} h-32 p-3 bg-slate-900 border-white/10 font-mono`}
            value={textInput}
            onChange={handleTextChange}
            placeholder="输入文案..."
          />
        </section>

        <section className="space-y-4">
          <h2 className="text-xs font-bold text-slate-500 uppercase border-b border-white/5 pb-2">物理质感</h2>

          <div>
            <label className="block text-[10px] text-slate-400 mb-1">材质选项</label>
            <select
              value={config.borderStyle}
              onChange={(e) => updateConfig({ borderStyle: e.target.value as BorderStyle })}
              className={`${inputBaseClass} p-2.5 bg-slate-900`}
            >
              {BORDER_STYLES.map(style => <option key={style.id} value={style.id}>{style.name}</option>)}
            </select>
          </div>

          <div>
            <label className="block text-[10px] text-slate-400 mb-1">色彩主题</label>
            <select
              value={config.colorScheme.name}
              onChange={(e) => {
                const scheme = COLOR_SCHEMES.find(s => s.name === e.target.value);
                if (scheme) updateConfig({ colorScheme: scheme });
              }}
              className={`${inputBaseClass} p-2.5 bg-slate-900`}
            >
              {COLOR_SCHEMES.map(s => <option key={s.name} value={s.name}>{s.name}</option>)}
            </select>
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-[10px] text-slate-400 mb-1">边框粗细</label>
              <input type="number" min="0" max="100" value={config.borderWidth} onChange={(e) => updateConfig({ borderWidth: Number(e.target.value) })} className={`${inputBaseClass} p-2`} />
            </div>
            <div>
              <label className="block text-[10px] text-slate-400 mb-1">预览角度</label>
              <input type="number" value={config.rotation} onChange={(e) => updateConfig({ rotation: Number(e.target.value) })} className={`${inputBaseClass} p-2`} />
            </div>
          </div>
        </section>

        <section className="space-y-4">
          <h2 className="text-xs font-bold text-slate-500 uppercase border-b border-white/5 pb-2">字体设置</h2>
          <select
            value={config.fontFamily}
            onChange={(e) => updateConfig({ fontFamily: e.target.value })}
            className={`${inputBaseClass} p-2.5 bg-slate-900`}
          >
            {CHINESE_FONTS.map(f => <option key={f.value} value={f.value}>{f.name}</option>)}
          </select>
          <div className="flex gap-2">
            <input type="number" min="8" max="80" value={config.fontSize} onChange={(e) => updateConfig({ fontSize: Number(e.target.value) })} className={`${inputBaseClass} p-2 w-20`} />
            <input type="color" value={config.fontColor} onChange={(e) => updateConfig({ fontColor: e.target.value })} className="flex-1 h-9 cursor-pointer rounded-lg border-none p-0 bg-transparent" />
          </div>
        </section>
      </div>

      {/* 第二列：AI */}
      <div className="w-full md:w-80 bg-slate-900 border-r border-white/5 flex flex-col h-full z-10">
        <div className="p-4 border-b border-white/5">
          <h2 className="text-xs font-black text-blue-400 uppercase tracking-widest">灵感策划师</h2>
        </div>
        <div className="flex-1 overflow-y-auto p-4 space-y-4">
          {chatHistory.map((msg, idx) => (
            <div key={idx} className={`p-3 rounded-xl text-xs leading-relaxed ${msg.role === 'user' ? 'bg-blue-600/20 text-blue-100' : 'bg-slate-800 text-slate-300'}`}>
              {msg.content}
              {msg.items && (
                <button onClick={() => applyAiItems(msg.items!)} className="mt-2 w-full py-2 bg-blue-600 hover:bg-blue-500 text-white rounded-lg font-bold transition-colors">
                  填入内容 ({msg.items.length})
                </button>
              )}
            </div>
          ))}
          {isAiLoading && <div className="text-[10px] text-slate-500 animate-pulse">AI 正在思考中...</div>}
        </div>
        <div className="p-4 bg-slate-950 border-t border-white/5">
          <div className="flex gap-2">
            <input type="text" value={chatInput} onChange={(e) => setChatInput(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && callAi()} placeholder="输入主题..." className={`${inputBaseClass} p-2.5`} />
            <button onClick={callAi} disabled={isAiLoading} className="px-4 py-2 bg-blue-600 rounded-lg text-xs font-bold disabled:opacity-50">发送</button>
          </div>
        </div>
      </div>

      {/* 第三列：预览展示区 - 切换为白色背景 */}
      <main className="flex-1 flex flex-col bg-white relative">
        <div className="absolute inset-0 opacity-10 pointer-events-none" style={{ backgroundImage: 'radial-gradient(#000 0.5px, transparent 0.5px)', backgroundSize: '30px 30px' }} />

        <div className="w-full p-5 bg-white border-b border-slate-100 flex items-center justify-between z-30 shadow-sm">
          <div>
            <h3 className="text-sm font-black text-slate-900 uppercase tracking-tight">Ultra HD Viewport</h3>
            <p className="text-[10px] text-slate-400 font-bold">TRANSPARENT PNG OUTPUT • REAL-TIME RENDER</p>
          </div>

          <button
            onClick={downloadImage}
            className="group py-3 px-8 bg-slate-900 text-white font-black rounded-xl shadow-xl transition-all hover:bg-slate-800 active:scale-95 flex items-center gap-2 text-sm"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
            导出高清转盘
          </button>
        </div>

        <div className="flex-1 relative flex items-center justify-center p-8 overflow-hidden">
          <div className="w-full h-full max-w-[85%] max-h-[85%] aspect-square relative flex items-center justify-center">
            <WheelCanvas 
              config={config} 
              exportScale={4} 
              onCanvasReady={(canvas) => { canvasRef.current = canvas; }} 
            />
          </div>
        </div>

        <div className="p-4 bg-slate-50 border-t border-slate-100 text-center text-[10px] text-slate-400 font-bold uppercase tracking-[0.3em] select-none">
          物理渲染引擎 • 当前质感: {config.borderStyle} • {config.items.length} 槽位
        </div>
      </main>
    </div>
  );
};

