  items: string[];
  colorScheme: ColorScheme;
  borderWidth: number;
  borderColor: string;
  borderStyle: BorderStyle;
  spokeWidth: number;
  spokeStyle: SpokeStyle;
  hubRadius: number;
  hubColor: string;
  fontSize: number;
  fontFamily: string;
  fontWeight: string;
  fontColor: string;
  fontStrokeWidth: number;
  fontStrokeColor: string;
  fontGradientEnabled: boolean;
  rotation: number;
  showText: boolean;
}

