import React, { useEffect, useRef } from 'react';
import { WheelConfig } from '../types';

interface WheelCanvasProps {
  config: WheelConfig;
  exportScale?: number;
  onCanvasReady?: (canvas: HTMLCanvasElement) => void;
}

export const WheelCanvas: React.FC<WheelCanvasProps> = ({ config, exportScale = 2, onCanvasReady }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const drawWheel = (canvas: HTMLCanvasElement, scale: number) => {
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const size = canvas.width;
    const center = size / 2;
    const outerRadius = (size / 2) - (15 * scale); // 留出一点阴影空间
    const radius = outerRadius - (config.borderWidth * scale);

    const { items, colorScheme, borderWidth, borderStyle, spokeWidth, spokeStyle, hubRadius, hubColor, fontSize, fontFamily, fontWeight, fontColor, rotation } = config;

    // 清除画布
    ctx.clearRect(0, 0, size, size);
    if (items.length === 0) return;

    const sliceAngle = (2 * Math.PI) / items.length;
    const rotationRad = (rotation * Math.PI) / 180;

    // 1. 绘制扇区 (Slices)
    items.forEach((item, i) => {
      const startAngle = i * sliceAngle + rotationRad;
      const endAngle = startAngle + sliceAngle;
      const baseColor = colorScheme.colors[i % colorScheme.colors.length];

      ctx.save();
      ctx.beginPath();
      ctx.moveTo(center, center);
      ctx.arc(center, center, radius, startAngle, endAngle);
      ctx.closePath();

      ctx.fillStyle = baseColor;
      ctx.fill();

      // 应用扇区物理质感
      if (colorScheme.texture && colorScheme.texture !== 'none') {
        ctx.clip();
        switch (colorScheme.texture) {
          case 'silk': {
            const silkGrad = ctx.createLinearGradient(center + Math.cos(startAngle) * radius, center + Math.sin(startAngle) * radius, center + Math.cos(endAngle) * radius, center + Math.sin(endAngle) * radius);
            silkGrad.addColorStop(0, 'rgba(255,255,255,0.1)');
            silkGrad.addColorStop(0.5, 'rgba(255,255,255,0.3)');
            silkGrad.addColorStop(1, 'rgba(255,255,255,0.1)');
            ctx.fillStyle = silkGrad;
            ctx.fillRect(0, 0, size, size);
            break;
          }
          case 'frosted': {
            ctx.globalAlpha = 0.15;
            for (let j = 0; j < 500; j++) {
              ctx.fillStyle = Math.random() > 0.5 ? '#fff' : '#000';
              ctx.fillRect(center + (Math.random()-0.5)*radius*2, center + (Math.random()-0.5)*radius*2, scale, scale);
            }
            ctx.globalAlpha = 1.0;
            break;
          }
          case 'pearl': {
            const pearlGrad = ctx.createRadialGradient(center, center, radius * 0.5, center, center, radius);
            pearlGrad.addColorStop(0, 'rgba(255,255,255,0)');
            pearlGrad.addColorStop(1, 'rgba(255,255,255,0.4)');
            ctx.fillStyle = pearlGrad;
            ctx.fill();
            break;
          }
          case 'crystal': {
            ctx.strokeStyle = 'rgba(255,255,255,0.3)';
            ctx.lineWidth = 1 * scale;
            ctx.beginPath(); ctx.moveTo(center,center); ctx.lineTo(center + Math.cos(startAngle+sliceAngle*0.3)*radius, center + Math.sin(startAngle+sliceAngle*0.3)*radius); ctx.stroke();
            break;
          }
          case 'matte': {
            const matteGrad = ctx.createRadialGradient(center, center, radius * 0.8, center, center, radius);
            matteGrad.addColorStop(0, 'transparent');
            matteGrad.addColorStop(1, 'rgba(0,0,0,0.1)');
            ctx.fillStyle = matteGrad;
            ctx.fill();
            break;
          }
          case 'neon': {
            const neonGrad = ctx.createRadialGradient(center, center, radius * 0.9, center, center, radius);
            neonGrad.addColorStop(0, 'transparent');
            neonGrad.addColorStop(1, 'rgba(255,255,255,0.5)');
            ctx.fillStyle = neonGrad;
            ctx.fill();
            break;
          }
        }
      }
      ctx.restore();

      // 2. 绘制轴 (Spokes)
      if (spokeStyle !== 'none' && spokeWidth > 0) {
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(center, center);
        ctx.lineTo(center + Math.cos(startAngle) * radius, center + Math.sin(startAngle) * radius);
        ctx.lineWidth = spokeWidth * scale;

        switch (spokeStyle) {
          case 'silver_wire': ctx.strokeStyle = 'rgba(255, 255, 255, 0.4)'; break;
          case 'golden_wire': 
            const goldGrad = ctx.createLinearGradient(center, center, center + Math.cos(startAngle) * radius, center + Math.sin(startAngle) * radius);
            goldGrad.addColorStop(0, '#8e5d0d'); goldGrad.addColorStop(0.5, '#fcf6ba'); goldGrad.addColorStop(1, '#b38728');
            ctx.strokeStyle = goldGrad;
            break;
          case 'etched_groove': ctx.strokeStyle = 'rgba(0, 0, 0, 0.25)'; break;
          case 'embossed_ridge': ctx.strokeStyle = 'rgba(255, 255, 255, 0.3)'; break;
          case 'neon_tube': 
            ctx.strokeStyle = '#00f3ff'; ctx.shadowBlur = 8 * scale; ctx.shadowColor = '#00f3ff';
            break;
          case 'dotted_perforation': ctx.setLineDash([2 * scale, 4 * scale]); ctx.strokeStyle = 'rgba(0,0,0,0.2)'; break;
          default: ctx.strokeStyle = 'rgba(255,255,255,0.15)';
        }
        ctx.stroke();
        ctx.restore();
      }

      // 3. 绘制文字
      if (config.showText) {
        ctx.save();
        ctx.translate(center, center);
        ctx.rotate(startAngle + sliceAngle / 2);
        ctx.textAlign = 'right';
        ctx.textBaseline = 'middle';
        ctx.fillStyle = fontColor;
        ctx.font = `${fontWeight} ${fontSize * scale}px ${fontFamily}`;
        const textRadius = radius - (25 * scale);
        ctx.fillText(item, textRadius, 0, radius * 0.75);
        ctx.restore();
      }
    });

    // 4. 物理质感边框 (Physical Texture Border)
    if (borderWidth > 0) {
      ctx.save();
      const bRadius = radius + (borderWidth * scale / 2);
      ctx.beginPath();
      ctx.arc(center, center, bRadius, 0, 2 * Math.PI);
      ctx.lineWidth = borderWidth * scale;

      const gradX1 = center - outerRadius, gradY1 = center - outerRadius;
      const gradX2 = center + outerRadius, gradY2 = center + outerRadius;

      switch (borderStyle) {
        case 'titanium': {
          const g = ctx.createConicGradient(rotationRad, center, center);
          g.addColorStop(0, '#2c3e50'); g.addColorStop(0.2, '#7f8c8d'); g.addColorStop(0.25, '#ffffff'); 
          g.addColorStop(0.3, '#7f8c8d'); g.addColorStop(0.5, '#2c3e50'); g.addColorStop(0.7, '#7f8c8d');
          g.addColorStop(0.75, '#ffffff'); g.addColorStop(0.8, '#7f8c8d'); g.addColorStop(1, '#2c3e50');
          ctx.strokeStyle = g;
          break;
        }
        case 'polished_gold': {
          const g = ctx.createConicGradient(rotationRad * 0.5, center, center);
          g.addColorStop(0, '#6d4c11'); g.addColorStop(0.1, '#fcf6ba'); g.addColorStop(0.2, '#b38728');
          g.addColorStop(0.5, '#fbf5b7'); g.addColorStop(0.8, '#b38728'); g.addColorStop(0.9, '#fcf6ba');
          g.addColorStop(1, '#6d4c11');
          ctx.strokeStyle = g;
          break;
        }
        case 'frosted_glass': {
          const g = ctx.createRadialGradient(center, center, radius, center, center, outerRadius);
          g.addColorStop(0, 'rgba(240,240,240,0.8)'); g.addColorStop(0.5, 'rgba(255,255,255,0.4)'); g.addColorStop(1, 'rgba(200,200,200,0.6)');
          ctx.strokeStyle = g;
          break;
        }
        case 'brushed_aluminum': {
          const g = ctx.createLinearGradient(gradX1, gradY1, gradX2, gradY2);
          g.addColorStop(0, '#bdc3c7'); g.addColorStop(0.5, '#ffffff'); g.addColorStop(1, '#bdc3c7');
          ctx.strokeStyle = g;
          ctx.stroke();
          ctx.save(); ctx.clip();
          ctx.lineWidth = 1 * scale; ctx.strokeStyle = 'rgba(0,0,0,0.05)';
          for (let i = 0; i < size * 2; i += 2 * scale) { ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i-size, size); ctx.stroke(); }
          ctx.restore();
          break;
        }
        case 'liquid_mercury': {
          const g = ctx.createConicGradient(rotationRad * 2, center, center);
          g.addColorStop(0, '#000'); g.addColorStop(0.2, '#888'); g.addColorStop(0.25, '#fff'); 
          g.addColorStop(0.3, '#888'); g.addColorStop(0.5, '#000'); g.addColorStop(0.75, '#fff'); g.addColorStop(1, '#000');
          ctx.strokeStyle = g;
          break;
        }
        case 'rose_quartz': {
          const g = ctx.createRadialGradient(center, center, radius, center, center, outerRadius);
          g.addColorStop(0, '#ffd1dc'); g.addColorStop(0.7, '#ffb7c5'); g.addColorStop(1, '#ffc0cb');
          ctx.strokeStyle = g;
          break;
        }
        case 'obsidian_chrome': {
          const g = ctx.createConicGradient(rotationRad, center, center);
          g.addColorStop(0, '#050505'); g.addColorStop(0.2, '#222'); g.addColorStop(0.25, '#eee'); 
          g.addColorStop(0.3, '#222'); g.addColorStop(0.5, '#050505'); g.addColorStop(0.7, '#222');
          g.addColorStop(0.75, '#eee'); g.addColorStop(0.8, '#222'); g.addColorStop(1, '#050505');
          ctx.strokeStyle = g;
          break;
        }
        case 'iridescent_pearl': {
          const g = ctx.createConicGradient(rotationRad, center, center);
          g.addColorStop(0, '#eef2f3'); g.addColorStop(0.2, '#ffe2e2'); g.addColorStop(0.4, '#e2ffef');
          g.addColorStop(0.6, '#e2e2ff'); g.addColorStop(0.8, '#fff9e2'); g.addColorStop(1, '#eef2f3');
          ctx.strokeStyle = g;
          break;
        }
        case 'champagne_satin': {
          const g = ctx.createLinearGradient(gradX1, gradY1, gradX2, gradY2);
          g.addColorStop(0, '#ead6ad'); g.addColorStop(0.5, '#f9f1e0'); g.addColorStop(1, '#ead6ad');
          ctx.strokeStyle = g;
          break;
        }
        case 'ceramic_white': {
          const g = ctx.createRadialGradient(center-outerRadius/3, center-outerRadius/3, 0, center, center, outerRadius);
          g.addColorStop(0, '#ffffff'); g.addColorStop(1, '#e8e8e8');
          ctx.strokeStyle = g;
          break;
        }
        case 'emerald_glass': {
          const g = ctx.createRadialGradient(center, center, radius, center, center, outerRadius);
          g.addColorStop(0, 'rgba(4, 120, 87, 0.9)'); g.addColorStop(1, 'rgba(6, 78, 59, 0.95)');
          ctx.strokeStyle = g;
          break;
        }
        case 'space_black_matte': {
          const g = ctx.createRadialGradient(center, center, radius, center, center, outerRadius);
          g.addColorStop(0, '#1a1a1a'); g.addColorStop(1, '#000000');
          ctx.strokeStyle = g;
          break;
        }
        case 'nebula_resin': {
          ctx.strokeStyle = '#020617'; ctx.stroke();
          ctx.save(); ctx.clip();
          const g = ctx.createConicGradient(rotationRad * 0.3, center, center);
          g.addColorStop(0, '#1e1b4b'); g.addColorStop(0.5, '#4c1d95'); g.addColorStop(1, '#1e1b4b');
          ctx.fillStyle = g; ctx.fillRect(0, 0, size, size);
          for (let i = 0; i < 50; i++) {
            ctx.fillStyle = '#fff';
            ctx.beginPath(); ctx.arc(center + (Math.random()-0.5)*outerRadius*2, center + (Math.random()-0.5)*outerRadius*2, scale*0.5, 0, Math.PI*2); ctx.fill();
          }
          ctx.restore();
          break;
        }
        default: ctx.strokeStyle = config.borderColor;
      }
      ctx.stroke();

      // 添加通用反光层
      const rim = ctx.createLinearGradient(gradX1, gradY1, gradX2, gradY2);
      rim.addColorStop(0, 'rgba(255,255,255,0.4)'); rim.addColorStop(0.5, 'rgba(255,255,255,0)'); rim.addColorStop(1, 'rgba(0,0,0,0.1)');
      ctx.strokeStyle = rim;
      ctx.stroke();
      ctx.restore();
    }

    // 5. 中央轴承
    if (hubRadius > 0) {
      ctx.save();
      ctx.beginPath(); ctx.arc(center, center, hubRadius * scale, 0, 2 * Math.PI);
      const hubGrad = ctx.createRadialGradient(center - hubRadius/3, center - hubRadius/3, 0, center, center, hubRadius * scale);
      hubGrad.addColorStop(0, '#fff'); hubGrad.addColorStop(0.7, hubColor); hubGrad.addColorStop(1, '#666');
      ctx.fillStyle = hubGrad; ctx.fill();
      ctx.restore();
    }
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const scale = exportScale;
    canvas.width = 1000 * scale;
    canvas.height = 1000 * scale;
    drawWheel(canvas, scale);
    if (onCanvasReady) onCanvasReady(canvas);
  }, [config, exportScale]);

  return (
    <div className="w-full h-full flex justify-center items-center bg-transparent p-0 overflow-hidden">
      <canvas ref={canvasRef} className="max-w-full max-h-full object-contain drop-shadow-[0_40px_80px_rgba(0,0,0,0.1)]" />
    </div>
  );
};
